import React, { Fragment, useEffect, useRef, useState } from 'react';
import Login from './pages/Login';
import { api, logout, importLineCooperatives } from './services/api';

// Le test catalogue PAY est réservé à l'administration et ne doit pas apparaître
// dans la navigation de l'espace coopérative, notamment depuis la page Planning.
if (typeof window !== 'undefined' && typeof MutationObserver !== 'undefined') {
  const hidePayCatalogForCooperative = () => {
    if (window.__currentTransportUser?.role !== 'Cooperative') return;
    document.querySelectorAll('button').forEach((button) => {
      if (button.textContent.trim() === 'Test catalogue PAY') button.remove();
    });
  };
  const payNavigationObserver = new MutationObserver(hidePayCatalogForCooperative);
  payNavigationObserver.observe(document.documentElement, { childList: true, subtree: true });
  window.setTimeout(hidePayCatalogForCooperative, 0);
}

const modules = { dashboard: 'Tableau de bord', cooperative: 'Coopératives', proprietaires: 'Propriétaires véhicules', ligne: 'Lignes', vehicules: 'Véhicules', chauffeurs: 'Chauffeurs', planning: 'Planning', manifold: 'MANIFOLD', documents: 'Gestion des documents', rapports: 'Rapports', 'pay-test': 'Test catalogue PAY', parametres: 'Paramètres' };
const moduleIcons = { dashboard: <SidebarIcon name="dashboard" />, cooperative: <SidebarIcon name="cooperative" />, proprietaires: <SidebarIcon name="proprietaires" />, ligne: <SidebarIcon name="ligne" />, vehicules: <SidebarIcon name="vehicules" />, chauffeurs: <SidebarIcon name="chauffeurs" />, planning: <SidebarIcon name="planning" />, manifold: <SidebarIcon name="manifold" />, rapports: <SidebarIcon name="rapports" />, 'pay-test': <SidebarIcon name="pay-test" />, documents: <SidebarIcon name="documents" />, parametres: <SidebarIcon name="parametres" /> };

function SidebarIcon({ name }) { const paths = { dashboard: 'M3 11.5 12 4l9 7.5M5 10v9h14v-9M9 19v-5h6v5', cooperative: 'M4 20c0-3 2.5-5 5.5-5S15 17 15 20M7 9a3 3 0 1 0 6 0 3 3 0 0 0-6 0M15 11a2.5 2.5 0 1 0 0-5', proprietaires: 'M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8M4 21a8 8 0 0 1 16 0M18 8h3m-1.5-1.5v3', ligne: 'M4 7h12M12 3l4 4-4 4M20 17H8m4 4-4-4 4-4', vehicules: 'M3 16l2-7h14l2 7M5 16v3h3v-3m8 0v3h3v-3M6 9l1-3h10l1 3', chauffeurs: 'M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8M4 21a8 8 0 0 1 16 0', planning: 'M6 3v3m12-3v3M4 8h16M5 5h14a1 1 0 0 1 1 1v13H4V6a1 1 0 0 1 1-1', rapports: 'M4 19V5m0 14h16M8 16v-4m4 4V8m4 8V5', 'pay-test': 'M4 5h16v14H4zM8 9h8M8 13h5', documents: 'M6 3h9l3 3v15H6zM15 3v4h4M9 12h6M9 16h6', parametres: 'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M4 12h2m12 0h2M12 4v2m0 12v2M6.3 6.3l1.4 1.4m8.6 8.6 1.4 1.4m0-11.4-1.4 1.4M7.7 16.3l-1.4 1.4' }; return <svg className="sidebar-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d={paths[name] || paths.documents} /></svg>; }

function DocumentPaperEditor() {
  const [tab, setTab] = useState('vehicules'); const [vehicles, setVehicles] = useState([]); const [drivers, setDrivers] = useState([]); const [selected, setSelected] = useState(''); const [dates, setDates] = useState({}); const [files, setFiles] = useState({}); const [message, setMessage] = useState(''); const [error, setError] = useState('');
  const load = () => Promise.all([api('admin/vehicules'), api('admin/chauffeurs')]).then(([vehicleData, driverData]) => { setVehicles(vehicleData.results || []); setDrivers(driverData.results || []); }).catch((errorValue) => setError(errorValue.message)); useEffect(() => { load(); }, []);
  const rows = tab === 'vehicules' ? vehicles : drivers; const fields = tab === 'vehicules' ? [['assurance', 'Assurance'], ['licence', 'Licence'], ['visiteTechnique', 'Visite technique']] : [['permis', 'Permis'], ['visitePermis', 'Visite permis']]; const choose = (event) => { const id = event.target.value; setSelected(id); const row = rows.find((item) => item.objectId === id); setDates(row?.documentDates || {}); setFiles({}); setMessage(''); }; const updateDate = (key, part, value) => setDates((old) => ({ ...old, [key]: { ...(old[key] || {}), [part]: value } })); const updateFile = (key, file) => setFiles((old) => ({ ...old, [key]: file })); const upload = async (file) => { if (!file) return ''; const reader = await new Promise((resolve, reject) => { const fr = new FileReader(); fr.onload = () => resolve(fr.result); fr.onerror = reject; fr.readAsDataURL(file); }); const result = await api('cooperative/upload', { method: 'POST', body: JSON.stringify({ filename: file.name, contentType: file.type, base64: reader }) }); return result.url || ''; }; const save = async (event) => { event.preventDefault(); setError(''); setMessage(''); if (!selected) return setError('Sélectionnez un véhicule ou un chauffeur.'); try { const documentFiles = {}; for (const [key, file] of Object.entries(files)) documentFiles[key] = await upload(file); await api(`admin/documents/${tab}/${selected}`, { method: 'PUT', body: JSON.stringify({ documentDates: dates, documentFiles }) }); setMessage('Les images et les dates ont été enregistrées avec succès.'); setFiles({}); load(); } catch (errorValue) { setError(errorValue.message); } }; const changeTab = (value) => { setTab(value); setSelected(''); setDates({}); setFiles({}); setMessage(''); setError(''); };
  return <section className="panel document-editor"><div className="panel-heading"><div><p className="eyebrow">MISE À JOUR</p><h2>Ajouter les papiers et leurs dates</h2><p className="muted">Ajoutez l’image, la date de début et la date de fin de chaque document.</p></div></div><div className="report-tabs"><button className={tab === 'vehicules' ? 'active' : ''} onClick={() => changeTab('vehicules')}>Documents véhicules</button><button className={tab === 'chauffeurs' ? 'active' : ''} onClick={() => changeTab('chauffeurs')}>Documents chauffeurs</button></div><form className="document-editor-form" onSubmit={save}><label>{tab === 'vehicules' ? 'Véhicule' : 'Chauffeur'}<select value={selected} onChange={choose} required><option value="">Sélectionner…</option>{rows.map((row) => <option key={row.objectId} value={row.objectId}>{tab === 'vehicules' ? (row.numero || row.immatriculation) : `${row.nom || ''} ${row.prenom || ''}`.trim()}</option>)}</select></label><div className="document-paper-grid">{fields.map(([key, label]) => <article className="document-paper-card" key={key}><h3>{label}</h3><label>Image du document<input type="file" accept="image/*" onChange={(event) => updateFile(key, event.target.files?.[0])} /></label><div className="document-date-grid"><label>Date début<input type="date" value={dates[key]?.start || ''} onChange={(event) => updateDate(key, 'start', event.target.value)} /></label><label>Date fin<input type="date" value={dates[key]?.end || ''} onChange={(event) => updateDate(key, 'end', event.target.value)} /></label></div></article>)}</div>{message && <div className="alert success">{message}</div>}{error && <div className="alert error">{error}</div>}<button type="submit">Enregistrer les documents</button></form></section>;
}

function AdminDocumentsShellWithPaperEditor({ user, onLogout, onBack, onNavigate }) { const show = (index) => document.querySelectorAll('.document-status-panel')[index]?.scrollIntoView({ behavior: 'smooth', block: 'start' }); return <div className="app-shell"><TopBar user={user} onLogout={onLogout} /><aside><FullSidebar user={user} active="documents" onNavigate={onNavigate} settingsOpen={false} onToggleSettings={() => onNavigate('parametres')} onSelectUsers={() => onNavigate('parametres')} /></aside><main><header><div><p className="eyebrow">ADMINISTRATION</p><h1>Gestion des documents</h1></div><button className="secondary-action" onClick={onBack}>Retour</button></header><DocumentPaperEditor /><div className="document-section-links"><button onClick={() => show(0)}>Voir expirés</button><button onClick={() => show(1)}>Voir bientôt expirés</button><button onClick={() => show(2)}>Voir à jour</button><button onClick={() => show(3)}>Voir dates manquantes</button></div><AdminDocuments /></main></div>; }

function DocumentPaperEditorV2() { const [tab, setTab] = useState('vehicules'); const [vehicles, setVehicles] = useState([]); const [drivers, setDrivers] = useState([]); const [selected, setSelected] = useState(''); const [dates, setDates] = useState({}); const [files, setFiles] = useState({}); const [verso, setVerso] = useState({}); const [message, setMessage] = useState(''); const [error, setError] = useState(''); const load = () => Promise.all([api('admin/vehicules'), api('admin/chauffeurs')]).then(([vehicleData, driverData]) => { setVehicles(vehicleData.results || []); setDrivers(driverData.results || []); }).catch((errorValue) => setError(errorValue.message)); useEffect(() => { load(); }, []); const rows = tab === 'vehicules' ? vehicles : drivers; const fields = tab === 'vehicules' ? [['assurance', 'Assurance'], ['licence', 'Licence'], ['visiteTechnique', 'Visite technique']] : [['permis', 'Permis'], ['visitePermis', 'Visite permis']]; const choose = (event) => { const id = event.target.value; setSelected(id); const row = rows.find((item) => item.objectId === id); setDates(row?.documentDates || {}); setFiles({}); setVerso(fields.reduce((result, [key]) => ({ ...result, [key]: Boolean(row?.documentFiles?.[`${key}Verso`]) }), {})); setMessage(''); }; const upload = async (file) => { if (!file) return ''; const reader = await new Promise((resolve, reject) => { const fr = new FileReader(); fr.onload = () => resolve(fr.result); fr.onerror = reject; fr.readAsDataURL(file); }); const result = await api('cooperative/upload', { method: 'POST', body: JSON.stringify({ filename: file.name, contentType: file.type, base64: reader }) }); return result.url || ''; }; const save = async (event) => { event.preventDefault(); setError(''); setMessage(''); if (!selected) return setError('Sélectionnez un véhicule ou un chauffeur.'); try { const documentFiles = {}; for (const [key, file] of Object.entries(files)) documentFiles[key] = await upload(file); for (const [key] of fields) if (verso[key] && files[`${key}Verso`]) documentFiles[`${key}Verso`] = await upload(files[`${key}Verso`]); for (const [key] of fields) if (!verso[key]) documentFiles[`${key}Verso`] = null; await api(`admin/documents/${tab}/${selected}`, { method: 'PUT', body: JSON.stringify({ documentDates: dates, documentFiles }) }); setMessage('Les documents, images et dates ont été enregistrés avec succès.'); setFiles({}); load(); } catch (errorValue) { setError(errorValue.message); } }; const changeTab = (value) => { setTab(value); setSelected(''); setDates({}); setFiles({}); setVerso({}); setMessage(''); setError(''); }; return <section className="panel document-editor"><div className="panel-heading"><div><p className="eyebrow">MISE À JOUR</p><h2>Ajouter les papiers et leurs dates</h2><p className="muted">Activez le verso uniquement pour les documents qui en possèdent un.</p></div></div><div className="report-tabs"><button className={tab === 'vehicules' ? 'active' : ''} onClick={() => changeTab('vehicules')}>Documents véhicules</button><button className={tab === 'chauffeurs' ? 'active' : ''} onClick={() => changeTab('chauffeurs')}>Documents chauffeurs</button></div><form className="document-editor-form" onSubmit={save}><label>{tab === 'vehicules' ? 'Véhicule' : 'Chauffeur'}<select value={selected} onChange={choose} required><option value="">Sélectionner…</option>{rows.map((row) => <option key={row.objectId} value={row.objectId}>{tab === 'vehicules' ? (row.numero || row.immatriculation) : `${row.nom || ''} ${row.prenom || ''}`.trim()}</option>)}</select></label><div className="document-paper-grid">{fields.map(([key, label]) => <article className="document-paper-card" key={key}><h3>{label}</h3><label>Image recto<input type="file" accept="image/*" onChange={(event) => setFiles((old) => ({ ...old, [key]: event.target.files?.[0] }))} /></label><label className="document-verso-check"><input type="checkbox" checked={Boolean(verso[key])} onChange={(event) => setVerso((old) => ({ ...old, [key]: event.target.checked }))} /> Ce document possède un verso</label>{verso[key] && <label>Image verso<input type="file" accept="image/*" onChange={(event) => setFiles((old) => ({ ...old, [`${key}Verso`]: event.target.files?.[0] }))} /></label>}<div className="document-date-grid"><label>Date début<input type="date" value={dates[key]?.start || ''} onChange={(event) => setDates((old) => ({ ...old, [key]: { ...(old[key] || {}), start: event.target.value } }))} /></label><label>Date fin<input type="date" value={dates[key]?.end || ''} onChange={(event) => setDates((old) => ({ ...old, [key]: { ...(old[key] || {}), end: event.target.value } }))} /></label></div></article>)}</div>{message && <div className="alert success">{message}</div>}{error && <div className="alert error">{error}</div>}<button type="submit">Enregistrer les documents</button></form></section>; }

function DocumentStatusTabs() { const [tab, setTab] = useState('vehicules'); const [status, setStatus] = useState('soon'); const [vehicles, setVehicles] = useState([]); const [drivers, setDrivers] = useState([]); useEffect(() => { Promise.all([api('admin/vehicules'), api('admin/chauffeurs')]).then(([vehicleData, driverData]) => { setVehicles(vehicleData.results || []); setDrivers(driverData.results || []); }); }, []); const rows = tab === 'vehicules' ? vehicles : drivers; const fields = tab === 'vehicules' ? [['assurance', 'Assurance'], ['licence', 'Licence'], ['visiteTechnique', 'Visite technique']] : [['permis', 'Permis'], ['visitePermis', 'Visite permis']]; const classify = (item, key) => { const end = item.documentDates?.[key]?.end; if (!end) return 'missing'; const days = Math.ceil((new Date(end) - new Date()) / 86400000); return days < 0 ? 'expired' : days <= 15 ? 'soon' : 'valid'; }; const labels = { expired: 'Expirés', soon: 'Bientôt expirés', valid: 'À jour', missing: 'Dates manquantes' }; const items = rows.flatMap((row) => fields.map(([key, label]) => ({ row, key, label, state: classify(row, key) }))).filter((item) => item.state === status); return <section className="panel document-status-tabs"><div className="panel-heading"><div><p className="eyebrow">SUIVI</p><h2>État des documents</h2><p className="muted">Consultez directement les documents selon leur état.</p></div></div><div className="report-tabs"><button className={tab === 'vehicules' ? 'active' : ''} onClick={() => setTab('vehicules')}>Véhicules</button><button className={tab === 'chauffeurs' ? 'active' : ''} onClick={() => setTab('chauffeurs')}>Chauffeurs</button></div><div className="document-status-filters">{Object.entries(labels).map(([key, label]) => <button className={status === key ? 'active' : ''} onClick={() => setStatus(key)} key={key}>{label} <strong>{rows.flatMap((row) => fields.map(([field]) => classify(row, field))).filter((value) => value === key).length}</strong></button>)}</div><div className="document-status-list">{items.length ? items.map((item) => <div className="document-status-row" key={`${item.row.objectId}-${item.key}`}><strong>{tab === 'vehicules' ? (item.row.numero || item.row.immatriculation) : `${item.row.nom || ''} ${item.row.prenom || ''}`.trim()}</strong><span>{item.label} · fin : {item.row.documentDates?.[item.key]?.end || '—'}</span>{item.row.documentFiles?.[item.key] && <a href={item.row.documentFiles[item.key]} target="_blank" rel="noreferrer">Recto</a>}{item.row.documentFiles?.[`${item.key}Verso`] && <a href={item.row.documentFiles[`${item.key}Verso`]} target="_blank" rel="noreferrer">Verso</a>}</div>) : <p className="muted">Aucun document dans cette catégorie.</p>}</div></section>; }

function AdminDocumentsShellWithPaperEditorV2({ user, onLogout, onBack, onNavigate }) { return <div className="app-shell"><TopBar user={user} onLogout={onLogout} /><aside><FullSidebar user={user} active="documents" onNavigate={onNavigate} settingsOpen={false} onToggleSettings={() => onNavigate('parametres')} onSelectUsers={() => onNavigate('parametres')} /></aside><main><header><div><p className="eyebrow">ADMINISTRATION</p><h1>Gestion des documents</h1></div><button className="secondary-action" onClick={onBack}>Retour</button></header><DocumentPaperEditorV2 /><DocumentStatusTabs /></main></div>; }

function CarteGriseEditor() { const [vehicles, setVehicles] = useState([]); const [selected, setSelected] = useState(''); const [dates, setDates] = useState({}); const [files, setFiles] = useState({}); const [verso, setVerso] = useState(false); const [message, setMessage] = useState(''); const [error, setError] = useState(''); useEffect(() => { api('admin/vehicules').then((result) => setVehicles(result.results || [])).catch((errorValue) => setError(errorValue.message)); }, []); const choose = (event) => { const id = event.target.value; setSelected(id); const row = vehicles.find((item) => item.objectId === id); setDates(row?.documentDates?.carteGrise || {}); setVerso(Boolean(row?.documentFiles?.carteGriseVerso)); setFiles({}); setMessage(''); }; const upload = async (file) => { if (!file) return ''; const reader = await new Promise((resolve, reject) => { const fr = new FileReader(); fr.onload = () => resolve(fr.result); fr.onerror = reject; fr.readAsDataURL(file); }); const result = await api('cooperative/upload', { method: 'POST', body: JSON.stringify({ filename: file.name, contentType: file.type, base64: reader }) }); return result.url || ''; }; const save = async (event) => { event.preventDefault(); setError(''); setMessage(''); if (!selected) return setError('Sélectionnez un véhicule.'); try { const documentFiles = {}; if (files.recto) documentFiles.carteGrise = await upload(files.recto); if (verso && files.verso) documentFiles.carteGriseVerso = await upload(files.verso); if (!verso) documentFiles.carteGriseVerso = null; await api(`admin/documents/vehicules/${selected}`, { method: 'PUT', body: JSON.stringify({ documentDates: { carteGrise: dates }, documentFiles }) }); setMessage('La carte grise a été enregistrée avec succès.'); } catch (errorValue) { setError(errorValue.message); } }; return <section className="panel document-editor carte-grise-editor"><div className="panel-heading"><div><p className="eyebrow">DOCUMENT VÉHICULE</p><h2>Carte grise</h2><p className="muted">Ajoutez la carte grise et sa période de validité.</p></div></div><form className="document-editor-form" onSubmit={save}><label>Véhicule<select value={selected} onChange={choose} required><option value="">Sélectionner…</option>{vehicles.map((row) => <option key={row.objectId} value={row.objectId}>{row.numero || row.immatriculation || row.objectId}</option>)}</select></label><div className="document-paper-card"><label>Image recto<input type="file" accept="image/*" onChange={(event) => setFiles((old) => ({ ...old, recto: event.target.files?.[0] }))} /></label><label className="document-verso-check"><input type="checkbox" checked={verso} onChange={(event) => setVerso(event.target.checked)} /> Cette carte grise possède un verso</label>{verso && <label>Image verso<input type="file" accept="image/*" onChange={(event) => setFiles((old) => ({ ...old, verso: event.target.files?.[0] }))} /></label>}<div className="document-date-grid"><label>Date début<input type="date" value={dates.start || ''} onChange={(event) => setDates((old) => ({ ...old, start: event.target.value }))} /></label><label>Date fin<input type="date" value={dates.end || ''} onChange={(event) => setDates((old) => ({ ...old, end: event.target.value }))} /></label></div></div>{message && <div className="alert success">{message}</div>}{error && <div className="alert error">{error}</div>}<button type="submit">Enregistrer la carte grise</button></form></section>; }

function CarteGriseStatus() { const [vehicles, setVehicles] = useState([]); useEffect(() => { api('admin/vehicules').then((result) => setVehicles(result.results || [])); }, []); return <section className="panel document-status-tabs"><div className="panel-heading"><div><p className="eyebrow">VÉHICULES</p><h2>Cartes grises</h2></div><span className="result-count">{vehicles.filter((row) => row.documentDates?.carteGrise?.end).length} renseignée(s)</span></div><div className="document-status-list">{vehicles.map((row) => <div className="document-status-row" key={row.objectId}><strong>{row.numero || row.immatriculation || 'Véhicule'}</strong><span>Carte grise · fin : {row.documentDates?.carteGrise?.end || 'Date manquante'}</span>{row.documentFiles?.carteGrise && <a href={row.documentFiles.carteGrise} target="_blank" rel="noreferrer">Recto</a>}{row.documentFiles?.carteGriseVerso && <a href={row.documentFiles.carteGriseVerso} target="_blank" rel="noreferrer">Verso</a>}</div>)}</div></section>; }

function AdminDocumentsShellWithPaperEditorV3({ user, onLogout, onBack, onNavigate }) { return <div className="app-shell"><TopBar user={user} onLogout={onLogout} /><aside><FullSidebar user={user} active="documents" onNavigate={onNavigate} settingsOpen={false} onToggleSettings={() => onNavigate('parametres')} onSelectUsers={() => onNavigate('parametres')} /></aside><main><header><div><p className="eyebrow">ADMINISTRATION</p><h1>Gestion des documents</h1></div><button className="secondary-action" onClick={onBack}>Retour</button></header><DocumentPaperEditorV2 /><CarteGriseEditor /><DocumentStatusTabs /><CarteGriseStatus /></main></div>; }

function DocumentPaperEditorV4() { const [vehicles, setVehicles] = useState([]); const [selected, setSelected] = useState(''); const [dates, setDates] = useState({}); const [files, setFiles] = useState({}); const [verso, setVerso] = useState({}); const [message, setMessage] = useState(''); const [error, setError] = useState(''); const fields = [['assurance', 'Assurance'], ['licence', 'Licence'], ['carteGrise', 'Carte grise'], ['visiteTechnique', 'Visite technique']]; useEffect(() => { api('admin/vehicules').then((result) => setVehicles(result.results || [])).catch((errorValue) => setError(errorValue.message)); }, []); const choose = (event) => { const id = event.target.value; setSelected(id); const row = vehicles.find((item) => item.objectId === id); setDates(row?.documentDates || {}); setFiles({}); setVerso(fields.reduce((result, [key]) => ({ ...result, [key]: Boolean(row?.documentFiles?.[`${key}Verso`]) }), {})); setMessage(''); }; const upload = async (file) => { if (!file) return ''; const reader = await new Promise((resolve, reject) => { const fr = new FileReader(); fr.onload = () => resolve(fr.result); fr.onerror = reject; fr.readAsDataURL(file); }); const result = await api('cooperative/upload', { method: 'POST', body: JSON.stringify({ filename: file.name, contentType: file.type, base64: reader }) }); return result.url || ''; }; const save = async (event) => { event.preventDefault(); setError(''); setMessage(''); if (!selected) return setError('Sélectionnez un véhicule.'); try { const documentFiles = {}; for (const [key, file] of Object.entries(files)) documentFiles[key] = await upload(file); for (const [key] of fields) if (!verso[key]) documentFiles[`${key}Verso`] = null; await api(`admin/documents/vehicules/${selected}`, { method: 'PUT', body: JSON.stringify({ documentDates: dates, documentFiles }) }); setMessage('Les documents du véhicule ont été enregistrés avec succès.'); setFiles({}); } catch (errorValue) { setError(errorValue.message); } }; return <section className="panel document-editor"><div className="panel-heading"><div><p className="eyebrow">DOCUMENTS VÉHICULES</p><h2>Papiers du véhicule</h2><p className="muted">Carte grise est placée à côté de la visite technique.</p></div></div><form className="document-editor-form" onSubmit={save}><label>Véhicule<select value={selected} onChange={choose} required><option value="">Sélectionner…</option>{vehicles.map((row) => <option key={row.objectId} value={row.objectId}>{row.numero || row.immatriculation || row.objectId}</option>)}</select></label><div className="document-paper-grid">{fields.map(([key, label]) => <article className="document-paper-card" key={key}><h3>{label}</h3><label>Image recto<input type="file" accept="image/*" onChange={(event) => setFiles((old) => ({ ...old, [key]: event.target.files?.[0] }))} /></label><label className="document-verso-check"><input type="checkbox" checked={Boolean(verso[key])} onChange={(event) => setVerso((old) => ({ ...old, [key]: event.target.checked }))} /> Possède un verso</label>{verso[key] && <label>Image verso<input type="file" accept="image/*" onChange={(event) => setFiles((old) => ({ ...old, [`${key}Verso`]: event.target.files?.[0] }))} /></label>}<div className="document-date-grid"><label>Date début<input type="date" value={dates[key]?.start || ''} onChange={(event) => setDates((old) => ({ ...old, [key]: { ...(old[key] || {}), start: event.target.value } }))} /></label><label>Date fin<input type="date" value={dates[key]?.end || ''} onChange={(event) => setDates((old) => ({ ...old, [key]: { ...(old[key] || {}), end: event.target.value } }))} /></label></div></article>)}</div>{message && <div className="alert success">{message}</div>}{error && <div className="alert error">{error}</div>}<button type="submit">Enregistrer les documents</button></form></section>; }

function AdminDocumentsShellWithPaperEditorV4({ user, onLogout, onBack, onNavigate }) { return <div className="app-shell"><TopBar user={user} onLogout={onLogout} /><aside><FullSidebar user={user} active="documents" onNavigate={onNavigate} settingsOpen={false} onToggleSettings={() => onNavigate('parametres')} onSelectUsers={() => onNavigate('parametres')} /></aside><main><header><div><p className="eyebrow">ADMINISTRATION</p><h1>Gestion des documents</h1></div><button className="secondary-action" onClick={onBack}>Retour</button></header><DocumentPaperEditorV4 /><DocumentPaperEditorV2 /><DocumentStatusTabs /><CarteGriseStatus /></main></div>; }

function AdminDocumentsShellWithPaperEditorV5({ user, onLogout, onBack, onNavigate }) { return <div className="app-shell"><TopBar user={user} onLogout={onLogout} /><aside><FullSidebar user={user} active="documents" onNavigate={onNavigate} settingsOpen={false} onToggleSettings={() => onNavigate('parametres')} onSelectUsers={() => onNavigate('parametres')} /></aside><main><header><div><p className="eyebrow">ADMINISTRATION</p><h1>Gestion des documents</h1></div><button className="secondary-action" onClick={onBack}>Retour</button></header><DocumentPaperEditorV4 /><DocumentStatusTabs /><CarteGriseStatus /></main></div>; }

function VehicleDocumentStatus() { const [vehicles, setVehicles] = useState([]); const [search, setSearch] = useState(''); const [type, setType] = useState('all'); const [status, setStatus] = useState('all'); const fields = [['assurance', 'Assurance'], ['licence', 'Licence'], ['carteGrise', 'Carte grise'], ['visiteTechnique', 'Visite technique']]; useEffect(() => { api('admin/vehicules').then((result) => setVehicles(result.results || [])); }, []); const classify = (row, key) => { const end = row.documentDates?.[key]?.end; if (!end) return 'missing'; const days = Math.ceil((new Date(end) - new Date()) / 86400000); return days < 0 ? 'expired' : days <= 15 ? 'soon' : 'valid'; }; const labels = { all: 'Tous', expired: 'Expirés', soon: 'Bientôt expirés', valid: 'À jour', missing: 'Dates manquantes' }; const visible = vehicles.flatMap((row) => fields.map(([key, label]) => ({ row, key, label, state: classify(row, key) }))).filter((item) => { const number = `${item.row.numero || ''} ${item.row.immatriculation || ''}`.toLowerCase(); return number.includes(search.toLowerCase()) && (type === 'all' || item.key === type) && (status === 'all' || item.state === status); }); return <section className="panel document-status-tabs"><div className="panel-heading"><div><p className="eyebrow">SUIVI DES VÉHICULES</p><h2>État des documents</h2><p className="muted">Filtrez par numéro de véhicule et par type de document.</p></div></div><div className="document-status-search"><input className="search-input" value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Rechercher un numéro véhicule…" /><select value={type} onChange={(event) => setType(event.target.value)}><option value="all">Tous les types</option>{fields.map(([key, label]) => <option value={key} key={key}>{label}</option>)}</select></div><div className="document-status-filters">{Object.entries(labels).map(([key, label]) => <button className={status === key ? 'active' : ''} onClick={() => setStatus(key)} key={key}>{label}</button>)}</div><div className="document-status-list">{visible.length ? visible.map((item) => <div className="document-status-row" key={`${item.row.objectId}-${item.key}`}><strong>{item.row.numero || item.row.immatriculation || 'Véhicule'}</strong><span>{item.label} · fin : {item.row.documentDates?.[item.key]?.end || '—'}</span>{item.row.documentFiles?.[item.key] && <a href={item.row.documentFiles[item.key]} target="_blank" rel="noreferrer">Recto</a>}{item.row.documentFiles?.[`${item.key}Verso`] && <a href={item.row.documentFiles[`${item.key}Verso`]} target="_blank" rel="noreferrer">Verso</a>}</div>) : <p className="muted">Aucun document trouvé.</p>}</div></section>; }

function AdminDocumentsShellWithPaperEditorV7({ user, onLogout, onBack, onNavigate }) { return <div className="app-shell"><TopBar user={user} onLogout={onLogout} /><aside><FullSidebar user={user} active="documents" onNavigate={onNavigate} settingsOpen={false} onToggleSettings={() => onNavigate('parametres')} onSelectUsers={() => onNavigate('parametres')} /></aside><main><header><div><p className="eyebrow">ADMINISTRATION</p><h1>Gestion des documents</h1></div><button className="secondary-action" onClick={onBack}>Retour</button></header><DocumentPaperEditorV4 /><VehicleDocumentStatus /></main></div>; }

function DocumentControlPage() { const [rows, setRows] = useState([]); const [search, setSearch] = useState(''); const [loading, setLoading] = useState(true); useEffect(() => { api('controle-papiers').then((result) => setRows(result.results || [])).finally(() => setLoading(false)); }, []); const visible = rows.filter((row) => `${row.documentSubject || ''} ${row.numero || ''} ${row.immatriculation || ''}`.toLowerCase().includes(search.toLowerCase())); const docs = (row) => { const metadata = Array.isArray(row.documentMetadata) ? row.documentMetadata : []; if (metadata.length) return metadata; const keys = row.documentKind === 'Véhicule' ? [['assurance', 'Assurance'], ['licence', 'Licence'], ['carteGrise', 'Carte grise'], ['visiteTechnique', 'Visite technique']] : [['permis', 'Permis'], ['visitePermis', 'Visite permis']]; return keys.flatMap(([key, type]) => row.documentFiles?.[key] ? [{ type, url: row.documentFiles[key], orientation: 'recto' }] : []); }; return <section className="panel control-papers-page"><div className="panel-heading"><div><p className="eyebrow">ATT</p><h2>Contrôle papier</h2><p className="muted">Recherchez un numéro et consultez tous les documents associés.</p></div><span className="result-count">{visible.length} résultat(s)</span></div><input className="search-input" value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Rechercher par numéro véhicule…" />{loading ? <p className="muted">Chargement…</p> : <div className="control-paper-list">{visible.length ? visible.map((row) => <article className="control-paper-card" key={`${row.objectId}-${row.documentKind}`}><div><strong>{row.documentSubject}</strong><small>{row.documentKind}{row.immatriculation ? ` · ${row.immatriculation}` : ''}</small></div><div className="control-paper-documents">{docs(row).length ? docs(row).map((doc, index) => <a href={doc.url} target="_blank" rel="noreferrer" key={`${doc.type}-${doc.orientation}-${index}`}><b>{doc.type}</b><span>{doc.orientation || 'recto'}</span></a>) : <em>Aucun document enregistré</em>}</div></article>) : <p className="muted">Aucun résultat.</p>}</div>}</section>; }

function DocumentControlShell({ user, onLogout, onBack, onNavigate }) { return <div className="app-shell"><TopBar user={user} onLogout={onLogout} /><aside><FullSidebar user={user} active="controle-papiers" onNavigate={onNavigate} settingsOpen={false} onToggleSettings={() => onNavigate('parametres')} onSelectUsers={() => onNavigate('parametres')} /></aside><main><header><div><p className="eyebrow">ESPACE ATT</p><h1>Contrôle papier</h1></div><button className="secondary-action" onClick={onBack}>Retour</button></header><DocumentControlPage /></main></div>; }

function DocumentControlEditor() { const [vehicles, setVehicles] = useState([]); const [selected, setSelected] = useState(''); const [dates, setDates] = useState({}); const [files, setFiles] = useState({}); const [verso, setVerso] = useState({}); const [message, setMessage] = useState(''); const [error, setError] = useState(''); const fields = [['assurance', 'Assurance'], ['licence', 'Licence'], ['carteGrise', 'Carte grise'], ['visiteTechnique', 'Visite technique']]; const load = () => api('controle-papiers').then((result) => setVehicles((result.results || []).filter((row) => row.documentKind === 'Véhicule'))).catch((errorValue) => setError(errorValue.message)); useEffect(() => { load(); }, []); const choose = (event) => { const id = event.target.value; setSelected(id); const row = vehicles.find((item) => item.objectId === id); setDates(row?.documentDates || {}); setFiles({}); setVerso(fields.reduce((result, [key]) => ({ ...result, [key]: Boolean(row?.documentFiles?.[`${key}Verso`]) }), {})); setMessage(''); }; const upload = async (file) => { if (!file) return ''; const reader = await new Promise((resolve, reject) => { const fr = new FileReader(); fr.onload = () => resolve(fr.result); fr.onerror = reject; fr.readAsDataURL(file); }); const result = await api('cooperative/upload', { method: 'POST', body: JSON.stringify({ filename: file.name, contentType: file.type, base64: reader }) }); return result.url || ''; }; const save = async (event) => { event.preventDefault(); setError(''); setMessage(''); if (!selected) return setError('Sélectionnez un véhicule.'); try { const documentFiles = {}; for (const [key, file] of Object.entries(files)) documentFiles[key] = await upload(file); for (const [key] of fields) if (!verso[key]) documentFiles[`${key}Verso`] = null; await api(`admin/documents/vehicules/${selected}`, { method: 'PUT', body: JSON.stringify({ documentDates: dates, documentFiles }) }); setMessage('Les documents du véhicule ont été mis à jour avec succès.'); setFiles({}); load(); } catch (errorValue) { setError(errorValue.message); } }; return <section className="panel document-editor control-paper-editor"><div className="panel-heading"><div><p className="eyebrow">MISE À JOUR ATT</p><h2>Mettre à jour les papiers d’un véhicule</h2><p className="muted">Recherchez un numéro, remplacez les images et modifiez les dates.</p></div></div><form className="document-editor-form" onSubmit={save}><label>Rechercher un véhicule<select value={selected} onChange={choose} required><option value="">Sélectionner un véhicule…</option>{vehicles.map((row) => <option key={row.objectId} value={row.objectId}>{row.numero || row.immatriculation || row.objectId} {row.immatriculation ? `— ${row.immatriculation}` : ''}</option>)}</select></label><div className="document-paper-grid">{fields.map(([key, label]) => <article className="document-paper-card" key={key}><h3>{label}</h3><label>Nouvelle image recto<input type="file" accept="image/*" onChange={(event) => setFiles((old) => ({ ...old, [key]: event.target.files?.[0] }))} /></label><label className="document-verso-check"><input type="checkbox" checked={Boolean(verso[key])} onChange={(event) => setVerso((old) => ({ ...old, [key]: event.target.checked }))} /> Possède un verso</label>{verso[key] && <label>Nouvelle image verso<input type="file" accept="image/*" onChange={(event) => setFiles((old) => ({ ...old, [`${key}Verso`]: event.target.files?.[0] }))} /></label>}<div className="document-date-grid"><label>Date début<input type="date" value={dates[key]?.start || ''} onChange={(event) => setDates((old) => ({ ...old, [key]: { ...(old[key] || {}), start: event.target.value } }))} /></label><label>Date fin<input type="date" value={dates[key]?.end || ''} onChange={(event) => setDates((old) => ({ ...old, [key]: { ...(old[key] || {}), end: event.target.value } }))} /></label></div></article>)}</div>{message && <div className="alert success">{message}</div>}{error && <div className="alert error">{error}</div>}<button type="submit">Enregistrer les modifications</button></form></section>; }

const BaseDocumentControlShell = DocumentControlShell;
DocumentControlShell = function DocumentControlShellWithEditor({ user, onLogout, onBack, onNavigate }) { return <div className="app-shell"><TopBar user={user} onLogout={onLogout} /><aside><FullSidebar user={user} active="controle-papiers" onNavigate={onNavigate} settingsOpen={false} onToggleSettings={() => onNavigate('parametres')} onSelectUsers={() => onNavigate('parametres')} /></aside><main><header><div><p className="eyebrow">ESPACE ATT</p><h1>Contrôle papier</h1></div><button className="secondary-action" onClick={onBack}>Retour</button></header><DocumentControlEditor /><DocumentControlPage /></main></div>; };

function DocumentControlPageV2({ user }) { const [rows, setRows] = useState([]); const [search, setSearch] = useState(''); const fields = [['assurance', 'Assurance'], ['licence', 'Licence'], ['carteGrise', 'Carte grise'], ['visiteTechnique', 'Visite technique']]; useEffect(() => { api('controle-papiers').then((result) => setRows((result.results || []).filter((row) => row.documentKind === 'Véhicule'))); }, []); const classify = (row, key) => { const end = row.documentDates?.[key]?.end; if (!end) return ['missing', 'Manquant']; const days = Math.ceil((new Date(end) - new Date()) / 86400000); return days < 0 ? ['expired', 'Expiré'] : days <= 15 ? ['soon', 'Expire bientôt'] : ['valid', 'À jour']; }; const visible = rows.filter((row) => `${row.numero || ''} ${row.immatriculation || ''}`.toLowerCase().includes(search.toLowerCase())); return <section className="panel control-papers-page"><div className="panel-heading"><div><p className="eyebrow">ATT</p><h2>Contrôle papier</h2><p className="muted">Chaque type de document est affiché séparément avec son statut.</p></div><span className="result-count">{visible.length} véhicule(s)</span></div><input className="search-input" value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Rechercher par numéro véhicule ou immatriculation…" /><div className="control-document-table"><table><thead><tr><th>Véhicule</th><th>Type de document</th><th>Date début</th><th>Date fin</th><th>Statut</th><th>Fichiers</th><th>Action</th></tr></thead><tbody>{visible.flatMap((row) => fields.map(([key, label]) => { const [state, stateLabel] = classify(row, key); return <tr key={`${row.objectId}-${key}`}><td>{row.numero || row.immatriculation || '—'}</td><td>{label}</td><td>{row.documentDates?.[key]?.start || '—'}</td><td>{row.documentDates?.[key]?.end || '—'}</td><td><span className={`document-state ${state}`}>{stateLabel}</span></td><td className="row-actions">{row.documentFiles?.[key] && <a href={row.documentFiles[key]} target="_blank" rel="noreferrer">Recto</a>}{row.documentFiles?.[`${key}Verso`] && <a href={row.documentFiles[`${key}Verso`]} target="_blank" rel="noreferrer">Verso</a>}</td><td>{user.role === 'Admin' && <button className="action-button edit" onClick={() => document.querySelector('.control-paper-editor')?.scrollIntoView({ behavior: 'smooth' })}>Modifier</button>}</td></tr>; }))}</tbody></table>{!visible.length && <p className="muted">Aucun véhicule trouvé.</p>}</div></section>; }

function DocumentControlShellEnhanced({ user, onLogout, onBack, onNavigate }) { return <div className="app-shell"><TopBar user={user} onLogout={onLogout} /><aside><FullSidebar user={user} active="controle-papiers" onNavigate={onNavigate} settingsOpen={false} onToggleSettings={() => onNavigate('parametres')} onSelectUsers={() => onNavigate('parametres')} /></aside><main><header><div><p className="eyebrow">ESPACE ATT</p><h1>Contrôle papier</h1></div><button className="secondary-action" onClick={onBack}>Retour</button></header>{user.role === 'Admin' && <DocumentControlEditor />}<DocumentControlPageV2 user={user} /></main></div>; }

const EditableDocumentControlShell = DocumentControlShell;
DocumentControlShell = function RoleBasedDocumentControlShell({ user, onLogout, onBack, onNavigate }) { return <DocumentControlShellEnhanced user={user} onLogout={onLogout} onBack={onBack} onNavigate={onNavigate} />; };

function DocumentControlShellWithEditorForAll({ user, onLogout, onBack, onNavigate }) { return <div className="app-shell"><TopBar user={user} onLogout={onLogout} /><aside><FullSidebar user={user} active="controle-papiers" onNavigate={onNavigate} settingsOpen={false} onToggleSettings={() => onNavigate('parametres')} onSelectUsers={() => onNavigate('parametres')} /></aside><main><header><div><p className="eyebrow">ESPACE ATT</p><h1>Contrôle papier</h1></div><button className="secondary-action" onClick={onBack}>Retour</button></header><DocumentControlEditor /><DocumentControlPageV2 user={user} /></main></div>; }
DocumentControlShell = DocumentControlShellWithEditorForAll;

const BaseWorkspace = Workspace;
Workspace = function WorkspaceWithPaperControl({ user, onLogout }) { const page = window.location.pathname.slice(1) || 'dashboard'; if (page === 'controle-papiers') return <DocumentControlShell user={user} onLogout={onLogout} onBack={() => { window.history.pushState({}, '', '/'); window.location.reload(); }} onNavigate={(next) => { window.history.pushState({}, '', next === 'dashboard' ? '/' : `/${next}`); window.location.reload(); }} />; return <BaseWorkspace user={user} onLogout={onLogout} />; };

modules['controle-papiers'] = 'Contrôle papier';
moduleIcons['controle-papiers'] = <SidebarIcon name="controle-papiers" />;

function VehicleTableWithActions() { const [rows, setRows] = useState([]); const [page, setPage] = useState(1); const [selected, setSelected] = useState(null); const [message, setMessage] = useState(''); const [error, setError] = useState(''); const size = 10; const load = () => api('admin/vehicules').then((result) => setRows(result.results || [])).catch((errorValue) => setError(errorValue.message)); useEffect(() => { load(); }, []); const save = async (event) => { event.preventDefault(); const body = Object.fromEntries(new FormData(event.currentTarget).entries()); try { await api(`admin/vehicules/${selected.objectId}`, { method: 'PUT', body: JSON.stringify(body) }); setMessage('Véhicule modifié avec succès.'); setSelected(null); load(); } catch (errorValue) { setError(errorValue.message); } }; const pages = Math.max(1, Math.ceil(rows.length / size)); const visible = rows.slice((page - 1) * size, page * size); return <section className="panel"><div className="panel-heading"><div><p className="eyebrow">ADMINISTRATION</p><h2>Gestion des véhicules</h2></div><span className="result-count">{rows.length} véhicule(s)</span></div>{message && <div className="alert success">{message}</div>}{error && <div className="alert error">{error}</div>}<div className="table-wrap"><table><thead><tr><th>Numéro</th><th>Immatriculation</th><th>Modèle</th><th>Capacité</th><th>Statut</th><th>Actions</th></tr></thead><tbody>{visible.length ? visible.map((row) => <tr key={row.objectId}><td>{row.numero || row.numeroVehicule || '—'}</td><td>{row.immatriculation || '—'}</td><td>{row.modele || row.model || '—'}</td><td>{row.capacite || '—'}</td><td>{row.statut || 'Disponible'}</td><td><button className="action-button edit" onClick={() => setSelected(row)}>Modifier</button></td></tr>) : <tr><td colSpan="6" className="muted">Aucun véhicule.</td></tr>}</tbody></table></div><Pagination page={page} pages={pages} onChange={setPage} />{selected && <div className="modal-backdrop"><form className="modal-card form-modal" onSubmit={save}><button type="button" className="modal-close" onClick={() => setSelected(null)}>×</button><h2>Modifier le véhicule</h2><label>Numéro<input name="numero" defaultValue={selected.numero || selected.numeroVehicule || ''} required /></label><label>Immatriculation<input name="immatriculation" defaultValue={selected.immatriculation || ''} /></label><label>Modèle<input name="modele" defaultValue={selected.modele || selected.model || ''} /></label><label>Capacité<input name="capacite" type="number" min="1" defaultValue={selected.capacite || 18} /></label><label>Statut<select name="statut" defaultValue={selected.statut || 'Disponible'}><option>Disponible</option><option>En course</option><option>Maintenance</option></select></label><div className="modal-actions"><button type="submit">Enregistrer</button><button type="button" className="secondary-action" onClick={() => setSelected(null)}>Annuler</button></div></form></div>}</section>; }

const BaseAdminRegistry = AdminRegistry;
AdminRegistry = function AdminRegistryWithVehicleActions({ type }) { return type === 'vehicules' ? <><VehicleCreateForm /><VehicleTableWithActions /></> : <BaseAdminRegistry type={type} />; };

function VehiclePaperEditModal({ vehicle, onClose, onSaved }) { const fields = [['assurance', 'Assurance'], ['licence', 'Licence'], ['carteGrise', 'Carte grise'], ['visiteTechnique', 'Visite technique']]; const [dates, setDates] = useState(vehicle.documentDates || {}); const [files, setFiles] = useState({}); const [verso, setVerso] = useState(fields.reduce((result, [key]) => ({ ...result, [key]: Boolean(vehicle.documentFiles?.[`${key}Verso`]) }), {})); const [saving, setSaving] = useState(false); const [error, setError] = useState(''); const upload = async (file) => { if (!file) return ''; const reader = await new Promise((resolve, reject) => { const fr = new FileReader(); fr.onload = () => resolve(fr.result); fr.onerror = reject; fr.readAsDataURL(file); }); const result = await api('cooperative/upload', { method: 'POST', body: JSON.stringify({ filename: file.name, contentType: file.type, base64: reader }) }); return result.url || ''; }; const save = async (event) => { event.preventDefault(); setSaving(true); setError(''); try { const documentFiles = {}; for (const [key, file] of Object.entries(files)) if (file) documentFiles[key] = await upload(file); for (const [key] of fields) { if (verso[key] && files[`${key}Verso`]) documentFiles[`${key}Verso`] = await upload(files[`${key}Verso`]); if (!verso[key]) documentFiles[`${key}Verso`] = null; } await api(`admin/documents/vehicules/${vehicle.objectId}`, { method: 'PUT', body: JSON.stringify({ documentDates: dates, documentFiles }) }); onSaved(); } catch (errorValue) { setError(errorValue.message); } finally { setSaving(false); } }; return <div className="modal-backdrop"><form className="modal-card form-modal vehicle-paper-edit-modal" onSubmit={save}><button type="button" className="modal-close" onClick={onClose}>×</button><p className="eyebrow">MISE À JOUR</p><h2>Papiers · {vehicle.numero || 'Véhicule'}</h2><p className="muted">Ajoutez le recto et activez le verso uniquement si le document en possède un.</p>{fields.map(([key, label]) => <fieldset className="vehicle-paper-edit-field" key={key}><legend>{label}</legend><label>Image recto<input type="file" accept="image/*" onChange={(event) => setFiles((old) => ({ ...old, [key]: event.target.files?.[0] }))} /></label><label className="document-verso-check"><input type="checkbox" checked={Boolean(verso[key])} onChange={(event) => setVerso((old) => ({ ...old, [key]: event.target.checked }))} /> Ce document possède un verso</label>{verso[key] && <label>Image verso<input type="file" accept="image/*" onChange={(event) => setFiles((old) => ({ ...old, [`${key}Verso`]: event.target.files?.[0] }))} /></label>}<div className="document-date-grid"><label>Date début<input type="date" value={dates[key]?.start || ''} onChange={(event) => setDates((old) => ({ ...old, [key]: { ...(old[key] || {}), start: event.target.value } }))} /></label><label>Date fin<input type="date" value={dates[key]?.end || ''} onChange={(event) => setDates((old) => ({ ...old, [key]: { ...(old[key] || {}), end: event.target.value } }))} /></label></div></fieldset>)}{error && <div className="alert error">{error}</div>}<div className="modal-actions"><button type="submit" disabled={saving}>{saving ? 'Enregistrement…' : 'Enregistrer les papiers'}</button><button type="button" className="secondary-action" onClick={onClose}>Annuler</button></div></form></div>; }

function VehicleTableWithPlaceMax() { const [rows, setRows] = useState([]); const [selected, setSelected] = useState(null); const [details, setDetails] = useState(null); const [paperEdit, setPaperEdit] = useState(null); const [search, setSearch] = useState(''); const [page, setPage] = useState(1); const [message, setMessage] = useState(''); const [error, setError] = useState(''); const load = () => api('admin/vehicules').then((result) => setRows(result.results || [])).catch((errorValue) => setError(errorValue.message)); useEffect(() => { load(); }, []); const size = 10; const filtered = rows.filter((row) => `${row.numero || ''} ${row.modele || row.model || ''} ${row.statut || ''}`.toLocaleLowerCase('fr-FR').includes(search.toLocaleLowerCase('fr-FR'))); const pages = Math.max(1, Math.ceil(filtered.length / size)); const visible = filtered.slice((page - 1) * size, page * size); const save = async (event) => { event.preventDefault(); const body = Object.fromEntries(new FormData(event.currentTarget).entries()); try { await api(`admin/vehicules/${selected.objectId}`, { method: 'PUT', body: JSON.stringify(body) }); setMessage('Véhicule modifié avec succès.'); setSelected(null); load(); } catch (errorValue) { setError(errorValue.message); } }; const personName = (person) => person ? (`${person.nom || ''} ${person.prenom || ''}`.trim() || person.name || person.objectId) : 'Non renseigné'; const relationName = (relation) => relation?.name || relation?.description || relation?.objectId || 'Non renseignée'; const paperStatus = (row, key) => { const end = row.documentDates?.[key]?.end; if (!end) return 'missing'; return new Date(end) < new Date() ? 'expired' : 'valid'; }; const paperSummary = (row) => <div className="vehicle-paper-status-list">{[['assurance', 'Assurance'], ['licence', 'Licence'], ['carteGrise', 'Carte grise'], ['visiteTechnique', 'Visite technique']].map(([key, label]) => <span className={`vehicle-paper-status ${paperStatus(row, key)}`} key={key} title={label}>{label}: {paperStatus(row, key) === 'valid' ? 'À jour' : paperStatus(row, key) === 'expired' ? 'Expiré' : 'Manquant'}</span>)}</div>; const image = (value, label) => value ? <a className="vehicle-detail-image" href={value} target="_blank" rel="noreferrer"><img src={value} alt={label} /><span>{label}</span></a> : <div className="vehicle-detail-image missing"><span>{label}</span><small>Image manquante</small></div>; const paper = (key, label) => { const date = details?.documentDates?.[key] || {}; const file = details?.documentFiles?.[key]; return <article className="vehicle-paper-card"><div><strong>{label}</strong><span>{date.start || '—'} → {date.end || '—'}</span></div>{file ? <a href={file} target="_blank" rel="noreferrer">Voir le document</a> : <em>Document manquant</em>}</article>; }; return <section className="panel"><div className="panel-heading"><div><p className="eyebrow">ADMINISTRATION</p><h2>Gestion des véhicules</h2></div><span className="result-count">{filtered.length} véhicule(s)</span></div>{message && <div className="alert success">{message}</div>}{error && <div className="alert error">{error}</div>}<input className="search-input" value={search} onChange={(event) => { setSearch(event.target.value); setPage(1); }} placeholder="Rechercher par numéro, modèle ou statut…" /><div className="table-wrap"><table><thead><tr><th>Numéro</th><th>Modèle</th><th>Place max</th><th>Statut</th><th>État des papiers</th><th>Actions</th></tr></thead><tbody>{visible.length ? visible.map((row) => <tr key={row.objectId}><td>{row.numero || row.numeroVehicule || '—'}</td><td>{row.modele || row.model || '—'}</td><td>{row.placeMax || row.capacite || '—'}</td><td>{row.statut || 'Disponible'}</td><td>{paperSummary(row)}</td><td><button className="action-button" onClick={() => setDetails(row)}>Voir détails</button> <button className="action-button edit" onClick={() => setSelected(row)}>Modifier</button></td></tr>) : <tr><td colSpan="6" className="muted">Aucun véhicule TAXIBROUSSE.</td></tr>}</tbody></table></div><Pagination page={page} pages={pages} onChange={setPage} />{selected && <div className="modal-backdrop"><form className="modal-card form-modal" onSubmit={save}><button type="button" className="modal-close" onClick={() => setSelected(null)}>×</button><h2>Modifier le véhicule</h2><label>Numéro<input name="numero" defaultValue={selected.numero || selected.numeroVehicule || ''} required /></label><label>Modèle<input name="modele" defaultValue={selected.modele || selected.model || ''} /></label><label>Place max<input name="placeMax" type="number" min="1" defaultValue={selected.placeMax || selected.capacite || 18} required /></label><label>Statut<select name="statut" defaultValue={selected.statut || 'Disponible'}><option>Disponible</option><option>En course</option><option>Maintenance</option></select></label><div className="modal-actions"><button type="submit">Enregistrer</button><button type="button" className="secondary-action" onClick={() => setSelected(null)}>Annuler</button></div></form></div>}{details && <div className="modal-backdrop" onClick={() => setDetails(null)}><div className="modal-card vehicle-detail-modal" onClick={(event) => event.stopPropagation()}><button type="button" className="modal-close" onClick={() => setDetails(null)}>×</button><p className="eyebrow">FICHE VÉHICULE</p><h2>{details.numero || details.numeroVehicule || 'Véhicule'}</h2><div className="vehicle-detail-grid"><div><h3>Caractéristiques</h3><dl><dt>Numéro</dt><dd>{details.numero || '—'}</dd><dt>Modèle</dt><dd>{details.modele || details.model || '—'}</dd><dt>Places</dt><dd>{details.placeMax || details.capacite || '—'}</dd><dt>Statut</dt><dd>{details.statut || 'Disponible'}</dd></dl></div><div><h3>Affectations</h3><dl><dt>Chauffeur</dt><dd>{personName(details.chauffeur)}</dd><dt>Ligne</dt><dd>{relationName(details.ligne)}</dd><dt>Coopérative</dt><dd>{relationName(details.cooperative)}</dd></dl></div></div><div className="vehicle-detail-actions"><button type="button" className="action-button edit" onClick={() => { setPaperEdit(details); setDetails(null); }}>Modifier les papiers</button></div><h3 className="vehicle-detail-section-title">Papiers du véhicule</h3><div className="vehicle-paper-list">{paper('assurance', 'Assurance')}{paper('licence', 'Licence')}{paper('carteGrise', 'Carte grise')}{paper('visiteTechnique', 'Visite technique')}</div><h3 className="vehicle-detail-section-title">Documents et images</h3><div className="vehicle-detail-images">{image(details.photos?.front || details.photoFrontUrl, 'Photo devant')}{image(details.photos?.back || details.photoBackUrl, 'Photo derrière')}{image(details.photos?.left || details.photoLeftUrl, 'Photo gauche')}{image(details.photos?.right || details.photoRightUrl, 'Photo droite')}{image(details.photos?.interior || details.photoInteriorUrl, 'Photo intérieur')}</div></div></div>}{paperEdit && <VehiclePaperEditModal vehicle={paperEdit} onClose={() => setPaperEdit(null)} onSaved={() => { setPaperEdit(null); setMessage('Les papiers ont été mis à jour.'); load(); }} />}</section>; }

AdminRegistry = function AdminRegistryWithPlaceMax({ type }) { return type === 'vehicules' ? <><VehicleCreateForm /><VehicleTableWithPlaceMax /></> : <><DriverCreateForm /><DriverTableWithPermit /></>; };

function PlanningModelCatalogV2({ user }) { const [models, setModels] = useState([]); const [open, setOpen] = useState(false); const [error, setError] = useState(''); const [success, setSuccess] = useState(''); const days = ['Dim', 'Lun', 'Mar', 'Mer', 'Jeu', 'Ven', 'Sam']; const load = () => api('planning-models').then((result) => setModels(result.results || [])).catch((errorValue) => setError(errorValue.message)); useEffect(() => { load(); }, []); const submit = async (event) => { event.preventDefault(); setError(''); const form = event.currentTarget; const values = Object.fromEntries(new FormData(form).entries()); values.jours = days.filter((day) => values[`jour_${day}`]).join(','); values.name = values.name || `Planning ${values.destination}`; try { await api('planning-models', { method: 'POST', body: JSON.stringify(values) }); form.reset(); setOpen(false); setSuccess('Le modèle de planning a été créé avec succès.'); load(); } catch (errorValue) { setError(errorValue.message); } }; return <section className="panel planning-model-catalog"><div className="panel-heading"><div><p className="eyebrow">PLANNING TYPE</p><h2>Modèles de planning prévisionnel</h2><p className="muted">Définissez les départs types utilisables par les coopératives.</p></div>{user.role === 'Admin' && <button onClick={() => { setOpen(true); setError(''); }}>+ Créer un modèle</button>}</div>{success && <div className="alert success">{success}</div>}{error && <div className="alert error">{error}</div>}<div className="planning-model-cards planning-type-cards">{models.length ? models.map((model) => <article key={model.objectId}><strong>{model.destination || model.name || 'Planning type'}</strong><span>{model.heureIndicative || model.heure || 'Heure indicative non définie'} · {model.mode || 'Fixe'}</span><small>Capacité prévisionnelle : {model.capacitePrevisionnelle || model.places || 0} · Jours : {model.jours || '—'}</small></article>) : <p className="muted">Aucun modèle de planning créé.</p>}</div>{open && <div className="modal-backdrop"><form className="modal-card form-modal planning-type-form" onSubmit={submit}><button type="button" className="modal-close" onClick={() => setOpen(false)}>×</button><p className="eyebrow">NOUVEAU PLANNING TYPE</p><h2>Créer un modèle de planning</h2><label>Nom du modèle<input name="name" placeholder="Planning Fianarantsoa matin" /></label><label>Destination<input name="destination" placeholder="Fianarantsoa" required /></label><label>Heure indicative<input name="heureIndicative" type="time" /></label><label>Mode<select name="mode" defaultValue="Fixe"><option value="Fixe">Fixe</option><option value="Remplissage">Remplissage</option></select></label><label>Capacité prévisionnelle<input name="capacitePrevisionnelle" type="number" min="1" placeholder="18" required /></label><fieldset><legend>Jours de départ</legend><div className="planning-days">{days.map((day) => <label key={day}><input type="checkbox" name={`jour_${day}`} value={day} />{day}</label>)}</div></fieldset><div className="modal-actions"><button type="submit">Enregistrer</button><button type="button" className="secondary-action" onClick={() => setOpen(false)}>Annuler</button></div></form></div>}</section>; }

function PlanningModelCatalogV3({ user }) { const [models, setModels] = useState([]); const [open, setOpen] = useState(false); const [error, setError] = useState(''); const [success, setSuccess] = useState(''); const days = ['Dim', 'Lun', 'Mar', 'Mer', 'Jeu', 'Ven', 'Sam']; const load = () => api('planning-models').then((result) => setModels(result.results || [])).catch((errorValue) => setError(errorValue.message)); useEffect(() => { load(); }, []); const submit = async (event) => { event.preventDefault(); setError(''); const form = event.currentTarget; const values = Object.fromEntries(new FormData(form).entries()); values.jours = days.filter((day) => values[`jour_${day}`]).join(','); if (!values.jours) { setError('Sélectionnez au moins un jour de départ.'); return; } values.name = values.name || `Planning ${values.destination}`; try { await api('planning-models', { method: 'POST', body: JSON.stringify(values) }); form.reset(); setOpen(false); setSuccess('Le modèle de planning a été créé avec succès.'); load(); } catch (errorValue) { setError(errorValue.message); } }; return <section className="panel planning-model-catalog"><div className="panel-heading"><div><p className="eyebrow">PLANNING TYPE</p><h2>Modèles de planning prévisionnel</h2><p className="muted">Définissez les départs types utilisables par les coopératives.</p></div>{user.role === 'Admin' && <button onClick={() => { setOpen(true); setError(''); }}>+ Créer un modèle</button>}</div>{success && <div className="alert success">{success}</div>}{error && <div className="alert error">{error}</div>}<div className="planning-model-cards planning-type-cards">{models.length ? models.map((model) => <article key={model.objectId}><strong>{model.destination || model.name || 'Planning type'}</strong><span>{model.heureIndicative || model.heure || 'Heure non renseignée'} · {model.mode || 'Mode non renseigné'}</span><small>Capacité prévisionnelle : {model.capacitePrevisionnelle || model.places || 'Non renseignée'} · Jours : {model.jours || 'Non renseignés'}</small></article>) : <p className="muted">Aucun modèle de planning créé.</p>}</div>{open && <div className="modal-backdrop"><form className="modal-card form-modal planning-type-form" onSubmit={submit}><button type="button" className="modal-close" onClick={() => setOpen(false)}>×</button><p className="eyebrow">NOUVEAU PLANNING TYPE</p><h2>Créer un modèle de planning</h2><label>Nom du modèle<input name="name" placeholder="Planning Fianarantsoa matin" /></label><label>Destination<input name="destination" placeholder="Fianarantsoa" required /></label><label>Heure indicative<input name="heureIndicative" type="time" required /></label><label>Mode<select name="mode" defaultValue="Fixe"><option value="Fixe">Fixe</option><option value="Remplissage">Remplissage</option></select></label><label>Capacité prévisionnelle<input name="capacitePrevisionnelle" type="number" min="1" placeholder="18" required /></label><fieldset><legend>Jours de départ</legend><div className="planning-days">{days.map((day) => <label key={day}><input type="checkbox" name={`jour_${day}`} value={day} />{day}</label>)}</div></fieldset><div className="modal-actions"><button type="submit">Enregistrer</button><button type="button" className="secondary-action" onClick={() => setOpen(false)}>Annuler</button></div></form></div>}</section>; }

PlanningModelCatalog = PlanningModelCatalogV3;

function PlanningModelGeneration() { const [models, setModels] = useState([]); const [model, setModel] = useState(''); const [startDate, setStartDate] = useState(''); const [endDate, setEndDate] = useState(''); const [frequence, setFrequence] = useState('Hebdomadaire'); const [message, setMessage] = useState(''); const [error, setError] = useState(''); useEffect(() => { api('planning-models').then((result) => setModels(result.results || [])); }, []); const generate = async (event) => { event.preventDefault(); setMessage(''); setError(''); if (!model || !startDate || !endDate) return setError('Sélectionnez un modèle et une période.'); try { const result = await api(`planning-models/${model}/generate`, { method: 'POST', body: JSON.stringify({ startDate, endDate, frequence }) }); setMessage(result.message || `${result.count || 0} départ(s) généré(s).`); } catch (errorValue) { setError(errorValue.message); } }; return <section className="panel planning-generation"><div className="panel-heading"><div><p className="eyebrow">GÉNÉRATION</p><h2>Générer depuis un modèle</h2><p className="muted">Créez les départs dans le planning prévisionnel à partir d’un modèle.</p></div></div><form className="planning-generation-form" onSubmit={generate}><label>Modèle<select value={model} onChange={(event) => setModel(event.target.value)} required><option value="">Sélectionner un modèle</option>{models.map((item) => <option key={item.objectId} value={item.objectId}>{item.destination || item.name} · {item.jours || 'Tous les jours'}</option>)}</select></label><label>Fréquence<select value={frequence} onChange={(event) => setFrequence(event.target.value)}><option value="Jour">Jour</option><option value="Hebdomadaire">Hebdomadaire</option><option value="Mensuel">Mensuel</option></select></label><label>Date début<input type="date" value={startDate} onChange={(event) => setStartDate(event.target.value)} required /></label><label>Date fin<input type="date" value={endDate} onChange={(event) => setEndDate(event.target.value)} required /></label><button type="submit">Générer le prévisionnel</button></form>{message && <div className="alert success">{message}</div>}{error && <div className="alert error">{error}</div>}</section>; }

function PlanningAssignmentFormV2() { const [models, setModels] = useState([]); const [vehicles, setVehicles] = useState([]); const [message, setMessage] = useState(''); const [error, setError] = useState(''); useEffect(() => { Promise.all([api('planning-models'), api('planning-vehicles')]).then(([modelData, vehicleData]) => { setModels(modelData.results || []); setVehicles(vehicleData.results || []); }).catch((errorValue) => setError(errorValue.message)); }, []); const submit = async (event) => { event.preventDefault(); setError(''); setMessage(''); const form = event.currentTarget; const body = Object.fromEntries(new FormData(form).entries()); try { await api('planning', { method: 'POST', body: JSON.stringify(body) }); form.reset(); setMessage('Le modèle a été affecté au véhicule avec succès.'); } catch (errorValue) { setError(errorValue.message); } }; return <section className="panel planning-assignment"><div className="panel-heading"><div><p className="eyebrow">AFFECTATION COOPÉRATIVE</p><h2>Utiliser un modèle de planning</h2><p className="muted">Affectez le modèle directement à un véhicule.</p></div></div><form className="planning-assignment-form" onSubmit={submit}><label>Modèle<select name="model" required><option value="">Sélectionner un modèle</option>{models.map((model) => <option key={model.objectId} value={model.objectId}>{model.destination || model.name} · {model.capacitePrevisionnelle || model.places || '—'} places</option>)}</select></label><label>Véhicule<select name="vehiculeNumero" required><option value="">Sélectionner un véhicule</option>{vehicles.map((vehicle) => <option key={vehicle.objectId} value={vehicle.numero || vehicle.numeroVehicule || vehicle.immatriculation}>{vehicle.numero || vehicle.numeroVehicule || vehicle.immatriculation} · {vehicle.placeMax || '—'} places</option>)}</select></label><label>Fréquence<select name="frequence" defaultValue="Jour" required><option value="Jour">Jour</option><option value="Hebdomadaire">Hebdomadaire</option><option value="Mensuel">Mensuel</option></select></label><label>Date départ<input name="date" type="date" required /></label><label>Départ<input name="depart" required /></label><label>Destination<input name="destination" required /></label><label>Places<input name="places" type="number" min="1" /></label><div className="modal-actions"><button type="submit">Affecter au véhicule</button></div></form>{message && <div className="alert success">{message}</div>}{error && <div className="alert error">{error}</div>}</section>; }

PlanningAssignmentForm = PlanningAssignmentFormV2;

const BasePlanningModelCatalog = PlanningModelCatalog;
PlanningModelCatalog = function PlanningModelCatalogWithGeneration({ user }) { return <><BasePlanningModelCatalog user={user} /><PlanningModelGeneration /></>; };

function PlanningCalendarV2() { const [models, setModels] = useState([]); const [plans, setPlans] = useState([]); const [month, setMonth] = useState(() => new Date()); const [view, setView] = useState('month'); const [selectedDay, setSelectedDay] = useState(new Date()); const dayNames = ['Dim', 'Lun', 'Mar', 'Mer', 'Jeu', 'Ven', 'Sam']; useEffect(() => { Promise.all([api('planning-models'), api('planning')]).then(([modelData, planData]) => { setModels(modelData.results || []); setPlans(planData.results || []); }); }, []); const year = month.getFullYear(); const monthIndex = month.getMonth(); const firstDay = (new Date(year, monthIndex, 1).getDay() + 6) % 7; const daysInMonth = new Date(year, monthIndex + 1, 0).getDate(); const cells = [...Array(firstDay).fill(null), ...Array.from({ length: daysInMonth }, (_, index) => index + 1)]; const matchesDay = (model, day) => { const date = new Date(year, monthIndex, day); const jours = String(model.jours || '').toLowerCase(); return jours.split(',').map((item) => item.trim()).includes(dayNames[date.getDay()].toLowerCase()); }; const modelsForDay = (day) => models.filter((model) => matchesDay(model, day)); const assignedIds = new Set(plans.map((plan) => plan.model?.objectId || plan.model)); const unassigned = models.filter((model) => !assignedIds.has(model.objectId)); const title = month.toLocaleDateString('fr-FR', { month: 'long', year: 'numeric' }); const event = (model) => <article className="planning-calendar-event"><strong>{model.destination || model.name || 'Planning type'}</strong><small>{model.heureIndicative || model.heure || 'Heure non renseignée'} · {model.mode || 'Fixe'}</small><em>{model.capacitePrevisionnelle || model.places || '—'} places</em></article>; const weekDays = Array.from({ length: 7 }, (_, index) => { const date = new Date(selectedDay); date.setDate(selectedDay.getDate() - ((selectedDay.getDay() + 6) % 7) + index); return date; }); return <section className="panel planning-calendar-panel"><div className="panel-heading calendar-toolbar"><div><p className="eyebrow">CALENDRIER DES MODÈLES</p><h2>Modèles prévisionnels</h2><p className="muted">Les modèles sont affichés selon leurs jours, même sans affectation.</p></div><div className="calendar-navigation"><button className="secondary-action" onClick={() => setMonth(new Date(year, monthIndex - 1, 1))}>‹</button><strong>{title.charAt(0).toUpperCase() + title.slice(1)}</strong><button className="secondary-action" onClick={() => setMonth(new Date(year, monthIndex + 1, 1))}>›</button></div></div><div className="calendar-view-tabs"><button className={view === 'month' ? 'active' : ''} onClick={() => setView('month')}>Mensuel</button><button className={view === 'week' ? 'active' : ''} onClick={() => setView('week')}>Hebdomadaire</button><button className={view === 'day' ? 'active' : ''} onClick={() => setView('day')}>Jour</button></div>{view === 'month' && <><div className="planning-calendar-weekdays">{['Lun', 'Mar', 'Mer', 'Jeu', 'Ven', 'Sam', 'Dim'].map((day) => <span key={day}>{day}</span>)}</div><div className="planning-calendar-grid">{cells.map((day, index) => <div className={`planning-calendar-cell ${day ? '' : 'empty'}`} key={`${day || 'empty'}-${index}`} onClick={() => day && setSelectedDay(new Date(year, monthIndex, day))}>{day && <><span className="calendar-day-number">{day}</span><div className="calendar-events">{modelsForDay(day).map((model) => <React.Fragment key={model.objectId}>{event(model)}</React.Fragment>)}</div></>}</div>)}</div></>}{view === 'week' && <div className="planning-week-view">{weekDays.map((date) => <article key={date.toISOString()}><h3>{date.toLocaleDateString('fr-FR', { weekday: 'long', day: 'numeric' })}</h3>{modelsForDay(date.getDate()).map((model) => <React.Fragment key={model.objectId}>{event(model)}</React.Fragment>)}</article>)}</div>}{view === 'day' && <div className="planning-day-view"><h3>{selectedDay.toLocaleDateString('fr-FR', { weekday: 'long', day: 'numeric', month: 'long' })}</h3>{modelsForDay(selectedDay.getDate()).map((model) => <React.Fragment key={model.objectId}>{event(model)}</React.Fragment>)}</div>}<div className="unassigned-models"><strong>Modèles non encore affectés : {unassigned.length}</strong>{unassigned.length > 0 && <span>{unassigned.map((model) => model.destination || model.name).join(' · ')}</span>}</div></section>; }

PlanningCalendar = PlanningCalendarV2;

function PlanningCalendarWithAssignments() {
  const [models, setModels] = useState([]); const [plans, setPlans] = useState([]); const [vehicles, setVehicles] = useState([]); const [drivers, setDrivers] = useState([]); const [month, setMonth] = useState(() => new Date()); const [view, setView] = useState('month'); const [selectedDay, setSelectedDay] = useState(new Date()); const [selectedDate, setSelectedDate] = useState(''); const [selectedModel, setSelectedModel] = useState(''); const [destination, setDestination] = useState(''); const [heure, setHeure] = useState(''); const [places, setPlaces] = useState(''); const [modal, setModal] = useState(false); const [error, setError] = useState(''); const [saving, setSaving] = useState(false);
  const load = () => Promise.all([api('planning-models'), api('planning'), api('planning-vehicles'), api('planning-drivers')]).then(([modelData, planData, vehicleData, driverData]) => { setModels(modelData.results || []); setPlans(planData.results || []); setVehicles(vehicleData.results || []); setDrivers(driverData.results || []); }).catch((errorValue) => setError(errorValue.message));
  useEffect(() => { load(); }, []);
  const dateKey = (date) => `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`;
  const year = month.getFullYear(); const monthIndex = month.getMonth(); const firstDay = (new Date(year, monthIndex, 1).getDay() + 6) % 7; const daysInMonth = new Date(year, monthIndex + 1, 0).getDate(); const cells = [...Array(firstDay).fill(null), ...Array.from({ length: daysInMonth }, (_, index) => index + 1)];
  const dayNames = ['Dim', 'Lun', 'Mar', 'Mer', 'Jeu', 'Ven', 'Sam']; const matchesDay = (model, day) => String(model.jours || '').toLowerCase().split(',').map((item) => item.trim()).includes(dayNames[new Date(year, monthIndex, day).getDay()].toLowerCase()); const modelsForDay = (day) => models.filter((model) => matchesDay(model, day)); const plansForDay = (day) => plans.filter((plan) => String(plan.date || '').slice(0, 10) === dateKey(new Date(year, monthIndex, day))); const title = month.toLocaleDateString('fr-FR', { month: 'long', year: 'numeric' });
  const openDay = (day) => { if (!day) return; const date = new Date(year, monthIndex, day); setSelectedDay(date); setSelectedDate(dateKey(date)); setSelectedModel(''); setDestination(''); setHeure(''); setPlaces(''); setError(''); setModal(true); };
  const chooseModel = (event) => { const modelId = event.target.value; const model = models.find((item) => item.objectId === modelId); setSelectedModel(modelId); setDestination(model?.destination || ''); setHeure(model?.heureIndicative || model?.heure || ''); };
  const chooseVehicle = (event) => { const vehicle = vehicles.find((item) => item.objectId === event.target.value); setPlaces(vehicle?.placeMax || vehicle?.capacite || vehicle?.places || ''); };
  const submit = async (event) => { event.preventDefault(); setSaving(true); setError(''); const values = Object.fromEntries(new FormData(event.currentTarget).entries()); const vehicle = vehicles.find((item) => item.objectId === values.vehicleId); const driver = drivers.find((item) => item.objectId === values.driverId); try { await api('planning', { method: 'POST', body: JSON.stringify({ model: values.model, date: selectedDate, depart: values.depart, destination: values.destination, heure: values.heure, places: values.places, vehiculeNumero: vehicle?.numero || vehicle?.numeroVehicule || vehicle?.immatriculation || '', chauffeurNom: `${driver?.nom || ''} ${driver?.prenom || ''}`.trim() }) }); setModal(false); load(); } catch (errorValue) { setError(errorValue.message); } finally { setSaving(false); } };
  const vehicleLabel = (vehicle) => vehicle.numero || vehicle.numeroVehicule || vehicle.immatriculation || 'Véhicule'; const driverLabel = (driver) => `${driver.nom || ''} ${driver.prenom || ''}`.trim() || driver.name || 'Chauffeur'; const weekDays = Array.from({ length: 7 }, (_, index) => { const date = new Date(selectedDay); date.setDate(selectedDay.getDate() - ((selectedDay.getDay() + 6) % 7) + index); return date; });
  const event = (model) => <article className="planning-calendar-event"><strong>{model.destination || model.name || 'Planning type'}</strong><small>{model.heureIndicative || model.heure || 'Heure non renseignée'} · {model.mode || 'Fixe'}</small><em>{model.capacitePrevisionnelle || model.places || '—'} places</em></article>;
  const assignment = (plan) => <article className="planning-calendar-event assigned"><strong>{plan.vehiculeNumero || 'Véhicule non affecté'}</strong><small>{plan.chauffeurNom || 'Chauffeur non affecté'}</small><em>{plan.depart || '—'} → {plan.destination || '—'}</em></article>;
  const dayContent = (day) => <>{modelsForDay(day).map((model) => <React.Fragment key={`model-${model.objectId}`}>{event(model)}</React.Fragment>)}{plansForDay(day).map((plan) => <React.Fragment key={`plan-${plan.objectId}`}>{assignment(plan)}</React.Fragment>)}</>;
  return <section className="panel planning-calendar-panel"><div className="panel-heading calendar-toolbar"><div><p className="eyebrow">CALENDRIER DES MODÈLES</p><h2>Modèles prévisionnels</h2><p className="muted">Cliquez sur une journée pour affecter un véhicule et un chauffeur.</p></div><div className="calendar-navigation"><button className="secondary-action" onClick={() => setMonth(new Date(year, monthIndex - 1, 1))}>‹</button><strong>{title.charAt(0).toUpperCase() + title.slice(1)}</strong><button className="secondary-action" onClick={() => setMonth(new Date(year, monthIndex + 1, 1))}>›</button></div></div><div className="calendar-view-tabs"><button className={view === 'month' ? 'active' : ''} onClick={() => setView('month')}>Mensuel</button><button className={view === 'week' ? 'active' : ''} onClick={() => setView('week')}>Hebdomadaire</button><button className={view === 'day' ? 'active' : ''} onClick={() => setView('day')}>Jour</button></div>{view === 'month' && <><div className="planning-calendar-weekdays">{['Lun', 'Mar', 'Mer', 'Jeu', 'Ven', 'Sam', 'Dim'].map((day) => <span key={day}>{day}</span>)}</div><div className="planning-calendar-grid">{cells.map((day, index) => <div className={`planning-calendar-cell ${day ? '' : 'empty'}`} key={`${day || 'empty'}-${index}`} onClick={() => openDay(day)}>{day && <><span className="calendar-day-number">{day}</span><div className="calendar-events">{dayContent(day)}</div></>}</div>)}</div></>}{view === 'week' && <div className="planning-week-view">{weekDays.map((date) => <article key={date.toISOString()} onClick={() => { setSelectedDay(date); setSelectedDate(dateKey(date)); setSelectedModel(''); setDestination(''); setHeure(''); setPlaces(''); setError(''); setModal(true); }}><h3>{date.toLocaleDateString('fr-FR', { weekday: 'long', day: 'numeric' })}</h3><div className="calendar-events">{dayContent(date.getDate())}</div></article>)}</div>}{view === 'day' && <div className="planning-day-view" onClick={() => openDay(selectedDay.getDate())}><h3>{selectedDay.toLocaleDateString('fr-FR', { weekday: 'long', day: 'numeric', month: 'long' })}</h3><div className="calendar-events">{dayContent(selectedDay.getDate())}</div></div>}{modal && <div className="modal-backdrop"><form className="modal-card form-modal planning-assignment-modal" onSubmit={submit}><button type="button" className="modal-close" onClick={() => setModal(false)}>×</button><p className="eyebrow">AFFECTATION DU {new Date(`${selectedDate}T00:00:00`).toLocaleDateString('fr-FR')}</p><h2>Ajouter un véhicule et un chauffeur</h2><label>Planning / destination<select name="model" required value={selectedModel} onChange={chooseModel}><option value="">Sélectionner un planning</option>{models.map((model) => <option key={model.objectId} value={model.objectId}>{model.destination || model.name} · {model.heureIndicative || model.heure || '—'}</option>)}</select></label><label>Véhicule<select name="vehicleId" required defaultValue="" onChange={chooseVehicle}><option value="">Sélectionner un véhicule</option>{vehicles.map((vehicle) => <option key={vehicle.objectId} value={vehicle.objectId}>{vehicleLabel(vehicle)}</option>)}</select></label><label>Chauffeur<select name="driverId" required defaultValue=""><option value="">Sélectionner un chauffeur</option>{drivers.map((driver) => <option key={driver.objectId} value={driver.objectId}>{driverLabel(driver)}</option>)}</select></label><label>Départ<input name="depart" required /></label><label>Destination<input name="destination" required value={destination} onChange={(event) => setDestination(event.target.value)} /></label><label>Heure<input name="heure" type="time" value={heure} onChange={(event) => setHeure(event.target.value)} required /></label><label>Places<input name="places" type="number" min="1" value={places} onChange={(event) => setPlaces(event.target.value)} required /></label>{error && <div className="alert error">{error}</div>}<div className="modal-actions"><button type="submit" disabled={saving}>{saving ? 'Enregistrement…' : 'Enregistrer l’affectation'}</button><button type="button" className="secondary-action" onClick={() => setModal(false)}>Annuler</button></div></form></div>}</section>;
}

PlanningCalendar = PlanningCalendarWithAssignments;

function PlanningCalendarSpec({ canManageTemplates = window.__currentTransportUser?.role === 'Admin' }) {
  const isAdmin = (window.__currentTransportUser || {}).role === 'Admin';
  useEffect(() => { const applyDestination = (event) => setDestinationFilter(event.detail || ''); window.addEventListener('planning-destination-filter', applyDestination); return () => window.removeEventListener('planning-destination-filter', applyDestination); }, []);
  const [models, setModels] = useState([]); const [plans, setPlans] = useState([]); const [vehicles, setVehicles] = useState([]); const [drivers, setDrivers] = useState([]); const [month, setMonth] = useState(() => new Date()); const [selectedDay, setSelectedDay] = useState(new Date()); const [view, setView] = useState('calendar'); const [route, setRoute] = useState(''); const [destinationFilter, setDestinationFilter] = useState(''); const [modal, setModal] = useState(null); const [selectedModel, setSelectedModel] = useState(''); const [vehicleId, setVehicleId] = useState(''); const [driverId, setDriverId] = useState(''); const [depart, setDepart] = useState(''); const [destination, setDestination] = useState(''); const [heure, setHeure] = useState(''); const [places, setPlaces] = useState(''); const [saving, setSaving] = useState(false); const [error, setError] = useState(''); const [message, setMessage] = useState('');
  const load = () => Promise.all([api('planning-models'), api('planning'), api('planning-vehicles'), api('planning-drivers')]).then(([modelData, planData, vehicleData, driverData]) => { setModels(modelData.results || []); setPlans(planData.results || []); setVehicles(vehicleData.results || []); setDrivers(driverData.results || []); }).catch((errorValue) => setError(errorValue.message)); useEffect(() => { load(); }, []);
  const dateKey = (date) => `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`; const selectedKey = dateKey(selectedDay); const year = month.getFullYear(); const monthIndex = month.getMonth(); const firstDay = (new Date(year, monthIndex, 1).getDay() + 6) % 7; const daysInMonth = new Date(year, monthIndex + 1, 0).getDate(); const cells = [...Array(firstDay).fill(null), ...Array.from({ length: daysInMonth }, (_, index) => index + 1)]; const title = month.toLocaleDateString('fr-FR', { month: 'long', year: 'numeric' });
  const planDate = (plan) => String(plan.date || '').slice(0, 10); const matchesFilters = (plan) => (!route || `${plan.depart}|${plan.destination}` === route) && (!destinationFilter || destinationKey(plan.destination) === destinationKey(destinationFilter)); const dayPlans = (key) => plans.filter((plan) => planDate(plan) === key && matchesFilters(plan)); const monthPlans = plans.filter((plan) => planDate(plan).startsWith(`${year}-${String(monthIndex + 1).padStart(2, '0')}-`)); const routes = [...new Map(plans.map((plan) => [`${plan.depart || ''}|${plan.destination || ''}`, plan])).values()]; const destinationOptions = [...new Set(plans.map((plan) => plan.destination).filter(Boolean))].sort(); const filteredMonthPlans = monthPlans.filter(matchesFilters); const assignedVehicles = new Set(filteredMonthPlans.map((plan) => plan.vehiculeNumero).filter(Boolean)); const destinations = new Set(filteredMonthPlans.map((plan) => plan.destination).filter(Boolean));
  const vehicleLabel = (vehicle) => vehicle.numero || vehicle.numeroVehicule || vehicle.immatriculation || 'Véhicule'; const driverLabel = (driver) => `${driver.nom || ''} ${driver.prenom || ''}`.trim() || driver.name || 'Chauffeur'; const openAssignment = (key, selectedPlan) => { const plan = selectedPlan?.objectId ? selectedPlan : (selectedPlan?.forceNew ? {} : (dayPlans(key).find((item) => !item.vehiculeNumero || !item.chauffeurNom) || {})); const model = models.find((item) => item.objectId === plan.model?.objectId || item.destination === plan.destination); const vehicle = vehicles.find((item) => vehicleLabel(item) === plan.vehiculeNumero); const driver = drivers.find((item) => driverLabel(item) === plan.chauffeurNom); setSelectedModel(plan.model?.objectId || model?.objectId || ''); setVehicleId(vehicle?.objectId || ''); setDriverId(driver?.objectId || ''); setDepart(plan.depart || ''); setDestination(plan.destination || model?.destination || ''); setHeure(plan.heure || ''); setPlaces(plan.places || ''); setModal({ type: 'assign', date: key, plan }); setError(''); };
  const chooseModel = (event) => { const modelId = event.target.value; const model = models.find((item) => item.objectId === modelId); setSelectedModel(modelId); setDestination(model?.destination || ''); setHeure(model?.heureIndicative || model?.heure || ''); }; const chooseVehicle = (event) => { const vehicle = vehicles.find((item) => item.objectId === event.target.value); setVehicleId(event.target.value); setPlaces(vehicle?.placeMax || vehicle?.capacite || vehicle?.places || ''); };
  const submit = async (event) => { event.preventDefault(); setSaving(true); setError(''); const vehicle = vehicles.find((item) => item.objectId === vehicleId); const driver = drivers.find((item) => item.objectId === driverId); const body = { model: selectedModel, date: modal.date, depart, destination, heure, places, vehiculeNumero: vehicleLabel(vehicle), chauffeurNom: driverLabel(driver) }; try { await api(modal.plan?.objectId ? `planning/${modal.plan.objectId}` : 'planning', { method: modal.plan?.objectId ? 'PUT' : 'POST', body: JSON.stringify(body) }); setModal(null); setMessage(modal.plan?.objectId ? 'Affectation modifiée avec succès.' : 'Départ enregistré avec succès.'); await load(); } catch (errorValue) { setError(errorValue.message); } finally { setSaving(false); } };
  const dayCell = (day) => { if (!day) return null; const key = dateKey(new Date(year, monthIndex, day)); const entries = dayPlans(key); const total = plans.filter((plan) => planDate(plan) === key).length; const assigned = plans.filter((plan) => planDate(plan) === key && plan.vehiculeNumero).length; const dots = [...new Set(entries.map((plan) => plan.destination).filter(Boolean))].slice(0, 4); return <button type="button" className={`planning-spec-day ${key === dateKey(new Date()) ? 'today' : ''}`} onClick={() => { setSelectedDay(new Date(year, monthIndex, day)); setView('day'); }}><strong>{day}</strong><span className="planning-spec-dots">{dots.map((item) => <i key={item} title={item} style={{ backgroundColor: destinationColor(item) }} />)}</span><small>{assigned}/{total} 🚐</small></button>; };
  const assignmentForm = <form className="planning-spec-form" onSubmit={submit}><label>Planning<select name="model" value={selectedModel} onChange={chooseModel} required><option value="">Sélectionner</option>{models.map((model) => <option key={model.objectId} value={model.objectId}>{model.destination || model.name}</option>)}</select></label><label>Véhicule<select name="vehicleId" value={vehicleId} required onChange={chooseVehicle}><option value="">Sélectionner</option>{vehicles.filter((vehicle) => vehicle.statut !== 'Maintenance').map((vehicle) => <option key={vehicle.objectId} value={vehicle.objectId}>{vehicleLabel(vehicle)}</option>)}</select></label><label>Chauffeur<select name="driverId" value={driverId} required onChange={(event) => setDriverId(event.target.value)}><option value="">Sélectionner</option>{drivers.map((driver) => <option key={driver.objectId} value={driver.objectId}>{driverLabel(driver)}</option>)}</select></label><label>Départ<input name="depart" required value={depart} onChange={(event) => setDepart(event.target.value)} /></label><label>Destination<input name="destination" required value={destination} onChange={(event) => setDestination(event.target.value)} /></label><label>Heure<input name="heure" type="time" required value={heure} onChange={(event) => setHeure(event.target.value)} /></label><label>Places<input name="places" type="number" min="1" required value={places} onChange={(event) => setPlaces(event.target.value)} /></label><div className="modal-actions"><button type="submit" disabled={saving}>{saving ? 'Enregistrement…' : 'Confirmer'}</button><button type="button" className="secondary-action" onClick={() => setModal(null)}>Annuler</button></div></form>;
  return <section className="panel planning-calendar-panel planning-spec"><div className="planning-spec-header"><div><p className="eyebrow">PLANNING COOPÉRATIVE</p><h2>📅 Planning mensuel</h2><p>{title.charAt(0).toUpperCase() + title.slice(1)}</p></div><div className="calendar-navigation"><button className="secondary-action" onClick={() => setMonth(new Date(year, monthIndex - 1, 1))}>‹</button><button className="secondary-action" onClick={() => setMonth(new Date(year, monthIndex + 1, 1))}>›</button></div></div><div className="planning-spec-kpis"><span>Départs <strong>{filteredMonthPlans.length}</strong></span><span>Véhicules <strong>{assignedVehicles.size}/{vehicles.length}</strong></span><span>Destinations <strong>{destinations.size}</strong></span></div>{message && <div className="alert success">{message}</div>}{error && <div className="alert error">{error}</div>}{view === 'calendar' && <><div className="planning-spec-toolbar"><select value={route} onChange={(event) => setRoute(event.target.value)}><option value="">Toutes les routes</option>{routes.map((item) => <option key={item.objectId} value={`${item.depart || ''}|${item.destination || ''}`}>{item.depart || '—'} → {item.destination || '—'}</option>)}</select><button type="button" onClick={() => setView('parking')}>🅿️ Parking</button>{canManageTemplates && <button type="button" onClick={() => document.querySelector('.planning-model-catalog')?.scrollIntoView({ behavior: 'smooth' })}>📋 Templates</button>}</div><div className="planning-calendar-weekdays">{['Lun', 'Mar', 'Mer', 'Jeu', 'Ven', 'Sam', 'Dim'].map((day) => <span key={day}>{day}</span>)}</div><div className="planning-calendar-grid planning-spec-grid">{cells.map((day, index) => <div className="planning-calendar-cell" key={`${day || 'empty'}-${index}`}>{dayCell(day)}</div>)}</div></>}{view === 'day' && <div className="planning-spec-day-view"><button type="button" className="secondary-action" onClick={() => setView('calendar')}>← Calendrier</button><h3>{selectedDay.toLocaleDateString('fr-FR', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' })}</h3><div className="planning-spec-departures">{dayPlans(selectedKey).map((plan) => <article key={plan.objectId}><strong>{plan.depart || '—'} → {plan.destination || '—'}</strong><span>{plan.heure || '—'} · {plan.vehiculeNumero || 'Véhicule non assigné'} · {plan.chauffeurNom || 'Chauffeur non assigné'}</span><button type="button" onClick={() => openAssignment(selectedKey, plan)}>Modifier l’affectation</button></article>)}{!dayPlans(selectedKey).length && <p className="muted">Aucun départ planifié.</p>}</div><button type="button" className="planning-spec-add" onClick={() => openAssignment(selectedKey)}>+ Ajouter un départ</button></div>}{view === 'parking' && <div className="planning-spec-parking"><button type="button" className="secondary-action" onClick={() => setView('calendar')}>← Planning</button><h3>🅿️ État du parking · {selectedDay.toLocaleDateString('fr-FR')}</h3>{vehicles.map((vehicle) => { const number = vehicleLabel(vehicle); const missions = plans.filter((plan) => planDate(plan) === selectedKey && plan.vehiculeNumero === number); return <article key={vehicle.objectId} className={missions.length ? 'in-service' : ''}><strong>{number}</strong><span>{vehicle.placeMax || vehicle.capacite || vehicle.places || '—'} places · {missions[0]?.chauffeurNom || 'Disponible'}</span><small>{missions.map((plan) => `${plan.heure || '—'} · ${plan.destination || '—'}`).join(' / ') || 'Aucune mission'}</small></article>; })}</div>}{modal && <div className="modal-backdrop"><div className="modal-card form-modal"><button type="button" className="modal-close" onClick={() => setModal(null)}>×</button><p className="eyebrow">DÉPART DU {new Date(`${modal.date}T00:00:00`).toLocaleDateString('fr-FR')}</p><h2>{modal.type === 'assign' ? 'Affecter un véhicule' : 'Ajouter un départ'}</h2>{assignmentForm}</div></div>}</section>;
}

