const PlanningCalendarBase = PlanningCalendar;
const DESTINATION_COLORS = { toamasina: '#F59E0B', antsirabe: '#10B981', mahajanga: '#3B82F6', fianarantsoa: '#7C3AED', toliara: '#EF4444', antsiranana: '#F97316', ambositra: '#EC4899', morondava: '#0891B2', antananarivo: '#DC2626' };
const DESTINATION_PALETTE = ['#2563EB', '#16A34A', '#D97706', '#9333EA', '#DB2777', '#0891B2', '#EA580C', '#4F46E5'];
const destinationKey = (destination) => String(destination || '').trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const destinationColor = (destination) => { const key = destinationKey(destination); if (DESTINATION_COLORS[key]) return DESTINATION_COLORS[key]; let hash = 0; for (const character of key) hash = (hash * 31 + character.charCodeAt(0)) % DESTINATION_PALETTE.length; return DESTINATION_PALETTE[hash] || '#6B7280'; };
function PlanningDestinationLegend() { return <div className="planning-destination-legend"><strong>Destinations</strong><label>Filtrer<select defaultValue="" onChange={(event) => window.dispatchEvent(new CustomEvent('planning-destination-filter', { detail: event.target.value }))}><option value="">Toutes</option>{Object.keys(DESTINATION_COLORS).map((destination) => <option key={destination} value={destination}>{destination.charAt(0).toUpperCase() + destination.slice(1)}</option>)}</select></label>{Object.keys(DESTINATION_COLORS).map((destination) => <span key={destination}><i style={{ backgroundColor: destinationColor(destination) }} />{destination.charAt(0).toUpperCase() + destination.slice(1)}</span>)}<span><i style={{ backgroundColor: destinationColor('Autres') }} />Autres</span></div>; }
const RouteTemplateWorkspace = ({ user }) => <><RouteTemplateCatalog user={user} /><PlanningModelGeneration /></>;
PlanningCalendar = function PlanningCalendarWithRouteTemplates(props) { useEffect(() => { const paint = () => document.querySelectorAll('.planning-spec-dots i[title]').forEach((dot) => { dot.style.backgroundColor = destinationColor(dot.title); }); const timer = window.setTimeout(paint, 150); return () => window.clearTimeout(timer); }, []); const currentUser = window.__currentTransportUser || { role: '' }; return <><RouteTemplateWorkspace user={currentUser} /><PlanningDestinationLegend /><PlanningCalendarBase {...props} /></>; };

class PlanningErrorBoundary extends React.Component { constructor(props) { super(props); this.state = { error: null }; } static getDerivedStateFromError(error) { return { error }; } componentDidCatch(error) { console.error('Erreur Planning:', error); } render() { return this.state.error ? <main><section className="panel"><h2>Le planning ne peut pas être chargé</h2><p className="alert error">{this.state.error.message || 'Erreur inattendue.'}</p><button onClick={() => window.location.reload()}>Recharger</button></section></main> : this.props.children; } }
const PlanningShellBeforeErrorBoundary = PlanningCalendarShell;
PlanningCalendarShell = (props) => <PlanningErrorBoundary><PlanningShellBeforeErrorBoundary {...props} /></PlanningErrorBoundary>;

export default function App() {
  const [user, setUser] = useState(null);
  useEffect(() => { api('auth/me').then((result) => setUser(result.user)).catch(() => setUser(false)); }, []);
  useEffect(() => { const onFileChange = (event) => { const input = event.target; if (input?.type !== 'file') return; const file = input.files?.[0]; if (!file) return; if (!file.type.startsWith('image/')) { window.alert('Seuls les fichiers image sont autorisés.'); input.value = ''; return; } const label = input.closest('label'); if (!label) return; let preview = label.querySelector('.image-preview'); if (!preview) { preview = document.createElement('img'); preview.className = 'image-preview'; preview.alt = 'Aperçu'; label.appendChild(preview); } preview.src = URL.createObjectURL(file); }; document.addEventListener('change', onFileChange, true); return () => document.removeEventListener('change', onFileChange, true); }, []);
  useEffect(() => { const onEditDocument = (event) => { const button = event.target.closest('.control-document-table button.action-button.edit'); if (!button) return; const row = button.closest('tr'); const number = row?.cells?.[0]?.textContent?.trim(); const select = document.querySelector('.control-paper-editor select'); const option = [...(select?.options || [])].find((item) => item.textContent.includes(number)); if (!select || !option) return; select.value = option.value; select.dispatchEvent(new Event('change', { bubbles: true })); setTimeout(() => document.querySelector('.control-paper-editor')?.scrollIntoView({ behavior: 'smooth', block: 'start' }), 0); }; document.addEventListener('click', onEditDocument); return () => document.removeEventListener('click', onEditDocument); }, []);
  if (user === null) return <div className="loading" role="status" aria-live="polite"><div className="loading-card"><img src="/logo.jpg" alt="CPP-Transport" /><div className="loading-spinner" aria-hidden="true" /><h1>CPP-Transport</h1><p>Préparation de votre espace…</p></div></div>;
  if (!user) return <Login onAuthenticated={setUser} />;
  window.__currentTransportUser = user;
  return <Workspace user={user} onLogout={async () => { await logout(); setUser(false); }} />;
}

function CooperativeVehiclesPage() { const [rows, setRows] = useState([]); const [search, setSearch] = useState(''); const [page, setPage] = useState(1); const size = 10; const [error, setError] = useState(''); useEffect(() => { api('admin/vehicules').then((result) => setRows(result.results || [])).catch((errorValue) => setError(errorValue.message)); }, []); const filtered = rows.filter((row) => `${row.numero || ''} ${row.modele || row.model || ''} ${row.statut || ''}`.toLocaleLowerCase('fr-FR').includes(search.toLocaleLowerCase('fr-FR'))); const pages = Math.max(1, Math.ceil(filtered.length / size)); const visible = filtered.slice((page - 1) * size, page * size); return <section className="panel"><div className="panel-heading"><div><p className="eyebrow">MA COOPÉRATIVE</p><h2>Mes véhicules</h2><p className="muted">Véhicules affectés à votre coopérative.</p></div><span className="result-count">{filtered.length} véhicule(s)</span></div>{error && <div className="alert error">{error}</div>}<input className="search-input" value={search} onChange={(event) => { setSearch(event.target.value); setPage(1); }} placeholder="Rechercher par numéro, modèle ou statut…" /><div className="table-wrap"><table><thead><tr><th>Numéro</th><th>Modèle</th><th>Places</th><th>Statut</th><th>Chauffeur</th><th>Ligne</th></tr></thead><tbody>{visible.length ? visible.map((row) => <tr key={row.objectId}><td>{row.numero || '—'}</td><td>{row.modele || row.model || '—'}</td><td>{row.placeMax || row.capacite || '—'}</td><td>{row.statut || 'Disponible'}</td><td>{row.chauffeur ? `${row.chauffeur.nom || ''} ${row.chauffeur.prenom || ''}`.trim() || row.chauffeur.name || '—' : '—'}</td><td>{row.ligne?.description || row.ligne?.name || '—'}</td></tr>) : <tr><td colSpan="6" className="muted">Aucun véhicule affecté à votre coopérative.</td></tr>}</tbody></table></div><Pagination page={page} pages={pages} onChange={setPage} /></section>; }

function CooperativeVehiclesShell({ user, onLogout, onNavigate }) { return <div className="app-shell cooperative-readonly"><TopBar user={user} onLogout={onLogout} /><aside><FullSidebar user={user} active="vehicules" onNavigate={onNavigate} settingsOpen={false} onToggleSettings={() => onNavigate('parametres')} onSelectUsers={() => onNavigate('parametres')} /></aside><main><VehicleTableWithPlaceMax /></main></div>; }

function CooperativeDashboard({ user, onNavigate }) {
  const [vehicles, setVehicles] = useState([]); const [lines, setLines] = useState([]); const [plans, setPlans] = useState([]); const [reservationStats, setReservationStats] = useState(null); const [loading, setLoading] = useState(true); const [error, setError] = useState('');
  useEffect(() => { Promise.allSettled([api('admin/vehicules'), api('ligne'), api('planning'), api('cooperative/reservation-stats')]).then(([vehicleResult, lineResult, planningResult, reservationResult]) => { if (vehicleResult.status === 'fulfilled') setVehicles(vehicleResult.value.results || []); if (lineResult.status === 'fulfilled') setLines(lineResult.value.results || []); if (planningResult.status === 'fulfilled') setPlans(planningResult.value.results || []); if (reservationResult.status === 'fulfilled') setReservationStats(reservationResult.value); const failure = [vehicleResult, lineResult, planningResult, reservationResult].find((result) => result.status === 'rejected'); if (failure) setError(failure.reason.message); }).finally(() => setLoading(false)); }, []);
  const today = localTodayKey(); const upcoming = plans.filter((plan) => String(plan.date || '') >= today).sort((a, b) => String(a.date || '').localeCompare(String(b.date || ''))).slice(0, 5); const activeVehicles = reservationStats?.today?.activeVehicles ?? vehicles.filter((row) => !['inactif', 'indisponible'].includes(String(row.statut || '').toLowerCase())).length;
  // Les réservations et les montants resteront à zéro jusqu’à réception des paramètres Parse.
  const currentReservationStats = reservationStats?.today || { reservations: 0, confirmed: 0, pending: 0, paid: 0, gross: 0, net: 0 };
  window.__cooperativeReservationStats = { ...currentReservationStats, periods: reservationStats || {} };
  const financialPeriods = [{ key: 'day', label: 'Aujourd’hui' }, { key: 'week', label: 'Cette semaine' }, { key: 'month', label: 'Ce mois' }];
  if (loading) return <section className="panel"><div className="dashboard-loading">Chargement de votre espace coopérative…</div></section>;
  return <div className="cooperative-dashboard"><section className="cooperative-hero"><div><p className="eyebrow">ESPACE COOPÉRATIVE</p><h2>Bonjour, {user.fullName || user.username} 👋</h2><p>Retrouvez votre flotte, vos lignes et vos prochains départs.</p></div><button onClick={() => onNavigate('planning')}>Ouvrir le planning</button></section>{error && <div className="alert error">{error}</div>}<div className="metric-grid cooperative-metrics"><Metric icon="▣" label="Véhicules actifs" value={activeVehicles} hint={`${vehicles.length} véhicule(s) affecté(s)`} /><Metric icon="↔" label="Lignes affectées" value={lines.length} hint="lignes de votre coopérative" /><Metric icon="◷" label="Prochains départs" value={upcoming.length} hint="départs à venir" /></div><div className="cooperative-dashboard-grid"><section className="panel"><div className="panel-heading"><div><p className="eyebrow">VOTRE RÉSEAU</p><h2>Mes lignes</h2></div><button className="secondary-action" onClick={() => onNavigate('ligne')}>Voir les lignes</button></div>{lines.length ? <div className="cooperative-line-list">{lines.slice(0, 6).map((line) => <div className="cooperative-line-row" key={line.objectId}><span className="line-icon">↔</span><div><strong>{line.description || 'Ligne sans nom'}</strong><small>Code : {line.displayCode || '—'}</small></div></div>)}</div> : <p className="muted">Aucune ligne n’est encore affectée à votre coopérative.</p>}</section><section className="panel"><div className="panel-heading"><div><p className="eyebrow">À VENIR</p><h2>Prochains départs</h2></div><button className="secondary-action" onClick={() => onNavigate('planning')}>Tout voir</button></div>{upcoming.length ? <div className="cooperative-plan-list">{upcoming.map((plan) => <div className="cooperative-plan-row" key={plan.objectId}><strong>{plan.date}</strong><div><span>{plan.depart || '—'} → {plan.destination || '—'}</span><small>{plan.heure || 'Heure à définir'} · {plan.vehiculeNumero || 'Véhicule à affecter'}</small></div></div>)}</div> : <p className="muted">Aucun départ planifié pour le moment.</p>}</section></div><section className="panel cooperative-dashboard-footer"><div><p className="eyebrow">GESTION RAPIDE</p><h2>Gérez votre activité</h2><p className="muted">Consultez vos véhicules et organisez les départs.</p></div><div className="panel-actions"><button onClick={() => onNavigate('vehicules')}>Mes véhicules</button><button onClick={() => onNavigate('planning')}>Mon planning</button></div></section></div>;
}

function ProprietairesPage() {
  const [rows, setRows] = useState([]); const [open, setOpen] = useState(false); const [step, setStep] = useState(1); const [form, setForm] = useState({ stat: 'Actif', validation: 'Non', approbation_coop: 'Non' }); const [page, setPage] = useState(1); const [search, setSearch] = useState(''); const [error, setError] = useState(''); const [success, setSuccess] = useState(''); const size = 10;
  const identityFields = [['nom', 'Nom'], ['prenom', 'Prénom'], ['date_de_naissance', 'Date de naissance', 'date'], ['CIN', 'CIN'], ['email', 'Email', 'email'], ['password', 'Mot de passe', 'password']];
  const contactFields = [['adresse', 'Adresse'], ['ville', 'Ville'], ['code_postal', 'Code postal'], ['pays', 'Pays'], ['phone', 'Téléphone']];
  const professionalFields = [['nif', 'NIF'], ['nom_operat', 'Nom opérateur'], ['number_flotte', 'Nombre flotte']];
  const load = () => api('proprietaires').then((result) => setRows(result.results || [])).catch((errorValue) => setError(errorValue.message));
  useEffect(() => { load(); }, []);
  const filtered = rows.filter((row) => (String(row.nom || '') + ' ' + String(row.prenom || '') + ' ' + String(row.email || '') + ' ' + String(row.phone || '') + ' ' + String(row.CIN || '')).toLocaleLowerCase('fr-FR').includes(search.toLocaleLowerCase('fr-FR')));
  const pages = Math.max(1, Math.ceil(filtered.length / size)); const visible = filtered.slice((page - 1) * size, page * size);
  const update = (event) => setForm((old) => ({ ...old, [event.target.name]: event.target.type === 'file' ? event.target.files?.[0] : event.target.value }));
  const field = ([name, label, type = 'text']) => <label key={name}>{label}<input name={name} type={type} value={form[name] || ''} onChange={update} required={['nom', 'prenom', 'email', 'password'].includes(name)} /></label>;
  const upload = async (file) => { if (!file) return ''; const reader = await new Promise((resolve, reject) => { const fileReader = new FileReader(); fileReader.onload = () => resolve(fileReader.result); fileReader.onerror = reject; fileReader.readAsDataURL(file); }); const result = await api('cooperative/upload', { method: 'POST', body: JSON.stringify({ filename: file.name, contentType: file.type, base64: reader }) }); return result.url || ''; };
  const submit = async (event) => { event.preventDefault(); setError(''); try { const body = { ...form, role: 'Proprietaire', stat: 'Actif', validation: 'Non', approbation_coop: 'Non' }; if (body.photo instanceof File) body.photo = await upload(body.photo); await api('proprietaires', { method: 'POST', body: JSON.stringify(body) }); setSuccess('Le propriétaire et son compte utilisateur ont été créés.'); setOpen(false); setStep(1); setForm({ stat: 'Actif', validation: 'Non', approbation_coop: 'Non' }); load(); } catch (errorValue) { setError(errorValue.message); } };
  const close = () => { setOpen(false); setStep(1); setForm({ stat: 'Actif', validation: 'Non', approbation_coop: 'Non' }); };
  return <section className="panel proprietaires-page"><div className="panel-heading"><div><p className="eyebrow">ADMINISTRATION</p><h2>Propriétaires de véhicules</h2><p className="muted">Gérez les propriétaires indépendamment des coopératives et créez leur accès utilisateur.</p></div><button onClick={() => { setError(''); setStep(1); setForm({ stat: 'Actif', validation: 'Non', approbation_coop: 'Non' }); setOpen(true); }}>+ Nouveau propriétaire</button></div>{success && <div className="alert success">{success}</div>}{error && <div className="alert error">{error}</div>}<input className="search-input" value={search} onChange={(event) => { setSearch(event.target.value); setPage(1); }} placeholder="Rechercher un propriétaire…" /><div className="table-wrap"><table><thead><tr><th>Nom</th><th>Email</th><th>Téléphone</th><th>CIN</th><th>Flotte</th><th>Statut</th></tr></thead><tbody>{visible.length ? visible.map((row) => <tr key={row.objectId}><td>{(String(row.prenom || '') + ' ' + String(row.nom || '')).trim() || '—'}</td><td>{row.email || row.user_id?.email || '—'}</td><td>{row.phone || '—'}</td><td>{row.CIN || '—'}</td><td>{row.number_flotte || '—'}</td><td>{row.actif === false ? 'Inactif' : row.stat || 'Actif'}</td></tr>) : <tr><td colSpan="6" className="muted">Aucun propriétaire enregistré.</td></tr>}</tbody></table></div><Pagination page={page} pages={pages} onChange={setPage} />{open && <div className="modal-backdrop"><form className="modal-card form-modal proprietaire-form" onSubmit={step === 3 ? submit : (event) => { event.preventDefault(); setStep((value) => value + 1); }}><button type="button" className="modal-close" onClick={close}>×</button><p className="eyebrow">NOUVEAU PROPRIÉTAIRE</p><h2>Créer un propriétaire et son compte</h2><div className="wizard-steps"><span className={step >= 1 ? 'active' : ''}>1. Identité</span><span className={step >= 2 ? 'active' : ''}>2. Coordonnées</span><span className={step >= 3 ? 'active' : ''}>3. Professionnel</span></div>{step === 1 && <div className="proprietaire-form-grid"><label>Photo du propriétaire<input name="photo" type="file" accept="image/*" onChange={update} /></label>{form.photo && <img className="proprietaire-photo-preview" src={URL.createObjectURL(form.photo)} alt="Aperçu du propriétaire" />}{identityFields.map(field)}</div>}{step === 2 && <div className="proprietaire-form-grid">{contactFields.map(field)}</div>}{step === 3 && <div className="proprietaire-form-grid">{professionalFields.map(field)}<label>Rôle<input value="Propriétaire" readOnly /></label><label>Statut<input value="Actif" readOnly /></label><label>Validation<input value="Non" readOnly /></label><label>Approbation coopérative<input value="Non" readOnly /></label></div>}<div className="modal-actions">{step > 1 && <button type="button" className="secondary-action" onClick={() => setStep((value) => value - 1)}>Précédent</button>}{step < 3 ? <button type="submit">Suivant</button> : <button type="submit">Créer le propriétaire</button>}<button type="button" className="secondary-action" onClick={close}>Annuler</button></div></form></div>}</section>;
}

function ProprietairesShell({ user, onLogout, onNavigate }) { return <div className="app-shell"><TopBar user={user} onLogout={onLogout} /><aside><FullSidebar user={user} active="proprietaires" onNavigate={onNavigate} settingsOpen={false} onToggleSettings={() => onNavigate('parametres')} onSelectUsers={() => onNavigate('parametres')} /></aside><main><header><div><p className="eyebrow">ESPACE ADMINISTRATION</p><h1>Propriétaires de véhicules</h1></div></header><ProprietairesPage /></main></div>; }

function ManifoldPage() {
  const [rows, setRows] = useState([]); const [search, setSearch] = useState(''); const [date, setDate] = useState(''); const [page, setPage] = useState(1); const [selected, setSelected] = useState(null); const [loading, setLoading] = useState(true); const [error, setError] = useState(''); const size = 10;
  useEffect(() => { api('manifold').then((result) => setRows(result.results || [])).catch((errorValue) => setError(errorValue.message)).finally(() => setLoading(false)); }, []);
  const readable = (value) => value && typeof value === 'object' ? (value.name || value.nom || value.description || value.objectId || '—') : String(value || '—');
  const filtered = rows.filter((row) => `${row.vehiculeNumero || ''} ${row.manifestNumber || row.numeroManifolds || row.numeroManifold || ''} ${row.destination || ''} ${row.koperativa || ''}`.toLocaleLowerCase('fr-FR').includes(search.toLocaleLowerCase('fr-FR')) && (!date || row.manifoldDay === date));
  const pages = Math.max(1, Math.ceil(filtered.length / size)); const visible = filtered.slice((page - 1) * size, page * size);
  return <section className="panel manifold-page"><div className="panel-heading"><div><p className="eyebrow">SUIVI DES DÉPARTS</p><h2>MANIFOLD</h2><p className="muted">Un seul manifeste par véhicule et par jour.</p></div><span className="result-count">{filtered.length} manifeste(s)</span></div><div className="list-toolbar"><input className="search-input" value={search} onChange={(event) => { setSearch(event.target.value); setPage(1); }} placeholder="Rechercher un véhicule, un manifeste ou une destination…" /><label className="manifold-date-filter">Date<input type="date" value={date} onChange={(event) => { setDate(event.target.value); setPage(1); }} /></label><button type="button" className="secondary-action" onClick={() => { setDate(''); setSearch(''); setPage(1); }}>Réinitialiser</button></div>{loading && <p className="muted">Chargement des manifolds…</p>}{error && <div className="alert error">{error}</div>}<div className="table-wrap"><table><thead><tr><th>Jour</th><th>Véhicule</th><th>N° manifeste</th><th>Destination</th><th>Chauffeur</th><th>Coopérative</th><th>Passagers</th><th>Action</th></tr></thead><tbody>{visible.length ? visible.map((row) => <tr key={`${row.vehiculeNumero}-${row.manifoldDay}`}><td>{row.manifoldDay || '—'}</td><td>{row.vehiculeNumero || '—'}</td><td>{row.manifestNumber || row.numeroManifolds || row.numeroManifold || row.manifoldObjectId || '—'}</td><td>{readable(row.destination)}</td><td>{readable(row.chauffeur)}</td><td>{readable(row.koperativa)}</td><td>{row.passengerCount ?? row.passengers ?? '—'}</td><td><button type="button" className="action-button edit" onClick={() => setSelected(row)}>Détails</button></td></tr>) : !loading && <tr><td colSpan="8" className="muted">Aucun manifold trouvé.</td></tr>}</tbody></table></div><Pagination page={page} pages={pages} onChange={setPage} />{selected && <div className="modal-backdrop"><div className="modal-card form-modal manifold-details-modal"><button type="button" className="modal-close" onClick={() => setSelected(null)}>×</button><p className="eyebrow">DÉTAILS DU MANIFOLD</p><h2>{selected.manifestNumber || selected.numeroManifolds || selected.numeroManifold || selected.manifoldObjectId || 'Manifeste'}</h2><div className="manifold-detail-grid"><span><small>Jour</small><strong>{selected.manifoldDay || '—'}</strong></span><span><small>Véhicule</small><strong>{selected.vehiculeNumero || '—'}</strong></span><span><small>Destination</small><strong>{readable(selected.destination)}</strong></span><span><small>Chauffeur</small><strong>{readable(selected.chauffeur)}</strong></span><span><small>Coopérative</small><strong>{readable(selected.koperativa)}</strong></span><span><small>Passagers</small><strong>{selected.passengerCount ?? selected.passengers ?? '—'}</strong></span><span><small>Quitus</small><strong>{selected.numero || selected.objectId || '—'}</strong></span><span><small>Date de départ</small><strong>{selected.departureDate || '—'}</strong></span></div><button type="button" className="secondary-action" onClick={() => setSelected(null)}>Fermer</button></div></div>}</section>;
}

function Workspace({ user, onLogout }) {
  const [page, setPage] = useState(window.location.pathname.slice(1) || 'dashboard');
  const navigate = (next) => { setPage(next); document.querySelector('.app-shell')?.classList.remove('mobile-menu-open'); window.history.pushState({}, '', next === 'dashboard' ? '/' : `/${next}`); };
  useEffect(() => { const onPopState = () => setPage(window.location.pathname.slice(1) || 'dashboard'); window.addEventListener('popstate', onPopState); return () => window.removeEventListener('popstate', onPopState); }, []);
  const canViewVehicles = user.role === 'Admin' || user.role === 'Cooperative';
  const visibleModules = Object.entries(modules).filter(([key]) => !['vehicules', 'chauffeurs', 'proprietaires', 'parametres', 'documents'].includes(key) || user.role === 'Admin' || (key === 'vehicules' && canViewVehicles) || (key === 'proprietaires' && user.role === 'Cooperative'));
  if (page === 'parametres' && user.role === 'Admin') return <AdminSettingsShellFull user={user} onLogout={onLogout} onBack={() => navigate('dashboard')} onNavigate={navigate} />;
  if (page === 'documents' && user.role === 'Admin') return <AdminDocumentsShellWithPaperEditorV7 user={user} onLogout={onLogout} onBack={() => navigate('dashboard')} onNavigate={navigate} />;
  if (page === 'controle-papiers') return <DocumentControlShellEnhanced user={user} onLogout={onLogout} onBack={() => navigate('dashboard')} onNavigate={navigate} />;
  if (page === 'pay-test' && user.role === 'Admin') return <PayCatalogTestShell user={user} onLogout={onLogout} onNavigate={navigate} />;
  if (page === 'proprietaires' && user.role === 'Admin') return <ProprietairesShell user={user} onLogout={onLogout} onNavigate={navigate} />;
  if (page === 'dashboard' && user.role === 'Cooperative') return <div className="app-shell"><TopBar user={user} onLogout={onLogout} /><aside><FullSidebar user={user} active="dashboard" onNavigate={navigate} settingsOpen={false} onToggleSettings={() => navigate('dashboard')} onSelectUsers={() => navigate('dashboard')} /></aside><main><header><div><p className="eyebrow">ESPACE COOPÉRATIVE</p><h1>Tableau de bord coopérative</h1></div></header><OccupancyPanel cooperativeView /><CooperativeDashboard user={user} onNavigate={navigate} /></main></div>;
  if (page === 'vehicules' && user.role === 'Cooperative') return <CooperativeVehiclesShell user={user} onLogout={onLogout} onNavigate={navigate} />;
  if (page === 'planning') return <PlanningCalendarShell user={user} onLogout={onLogout} onBack={() => navigate('dashboard')} onNavigate={navigate} />;
  if (page === 'cooperative' && user.role === 'Cooperative') return <CooperativeProfileShell user={user} onLogout={onLogout} onNavigate={navigate} />;
  return <div className="app-shell"><TopBar user={user} onLogout={onLogout} /><aside><div className="brand"><span>🚐</span><div><strong>CPP-Transport</strong><small>ESPACE TRANSPORT</small></div></div><nav>{visibleModules.map(([key, label]) => <button className={page === key ? 'active' : ''} onClick={() => navigate(key)} key={key}><b aria-hidden="true">{moduleIcons[key]}</b><span>{label}</span></button>)}</nav></aside><main><header><div><p className="eyebrow">ESPACE TRANSPORT</p><h1>{modules[page] || modules.dashboard} 👋</h1></div></header>{page === 'dashboard' ? <><OccupancyPanel /><Dashboard /></> : page === 'rapports' ? <RapportsTabs /> : page === 'manifold' ? <ManifoldPage /> : page === 'cooperative' ? <Cooperative /> : page === 'ligne' ? <Ligne isAdmin={user.role === 'Admin'} /> : page === 'vehicules' && user.role === 'Admin' ? <AdminRegistry type="vehicules" /> : page === 'chauffeurs' && user.role === 'Admin' ? <AdminRegistry type="chauffeurs" /> : <section className="panel"><h2>{modules[page] || modules.dashboard}</h2><p className="muted">Cette rubrique est disponible dans votre espace {user.role}.</p></section>}</main></div>;
}

function TopBar({ user, onLogout }) {
  window.__currentTransportUser = user;
  const initials = (user.fullName || user.username || 'U').split(/\s+/).map((part) => part[0]).join('').slice(0, 2).toUpperCase();
  const toggleMenu = () => document.querySelector('.app-shell')?.classList.toggle('mobile-menu-open');
  return <div className="topbar"><button className="mobile-menu-toggle" onClick={toggleMenu} aria-label="Ouvrir le menu">☰</button><div className="topbar-brand"><span className="brand-mark">🚐</span><strong>CPP-Transport</strong></div><div className="topbar-actions"><div className="topbar-user"><div className="topbar-avatar avatar-fallback">{initials}</div><div><strong>{user.fullName || user.username}</strong><small>{user.role}</small></div></div><button className="topbar-logout" onClick={onLogout}>Se déconnecter</button></div></div>;
}

function OccupancyPanel({ cooperativeView = false }) {
  const [rows, setRows] = useState([]); const [sourceCount, setSourceCount] = useState(0); const [search, setSearch] = useState(''); const [page, setPage] = useState(1); const [error, setError] = useState('');
  useEffect(() => { Promise.all([api('dashboard/occupancy'), cooperativeView ? api('planning') : Promise.resolve({ results: [] })]).then(([occupancyResult, planningResult]) => { const plans = planningResult.results || []; const today = localTodayKey(); const upcomingVehicles = [...new Set(plans.filter((plan) => String(plan.date || '') >= today).sort((a, b) => String(a.date || '').localeCompare(String(b.date || ''))).map((plan) => String(plan.vehiculeNumero || '').trim().toLocaleLowerCase('fr-FR')).filter(Boolean))]; const occupancyRows = occupancyResult.results || []; const orderedRows = cooperativeView && upcomingVehicles.length ? occupancyRows.filter((row) => upcomingVehicles.includes(String(row.vehicle || '').trim().toLocaleLowerCase('fr-FR'))).sort((a, b) => upcomingVehicles.indexOf(String(a.vehicle || '').trim().toLocaleLowerCase('fr-FR')) - upcomingVehicles.indexOf(String(b.vehicle || '').trim().toLocaleLowerCase('fr-FR'))) : occupancyRows; setRows(orderedRows); setSourceCount(Number(occupancyResult.sourceCount || 0)); }).catch((errorValue) => setError(errorValue.message)); }, [cooperativeView]);
  const emptyMessage = sourceCount ? 'Des réservations existent, mais aucun véhicule correspondant n’est rattaché à ce compte.' : 'Aucune réservation de place trouvée dans TaxibrousseSeatHold.';
  const filteredRows = rows.filter((row) => `${row.vehicle} ${row.day}`.toLocaleLowerCase('fr-FR').includes(search.toLocaleLowerCase('fr-FR')));
  const size = 10; const pages = Math.max(1, Math.ceil(filteredRows.length / size)); const visibleRows = filteredRows.slice((page - 1) * size, page * size);
  return <section className="panel occupancy-panel"><div className="panel-heading"><div><p className="eyebrow">{cooperativeView ? 'PROCHAINS DÉPARTS · REMPLISSAGE' : 'OCCUPATION DES VÉHICULES · AUJOURD’HUI'}</p><h2>Taux de remplissage</h2><p className="muted">{cooperativeView ? 'Véhicules correspondant aux prochains départs de votre coopérative.' : 'Places occupées d’après TaxibrousseSeatHold pour aujourd’hui.'}</p></div><span className="result-count">{filteredRows.length} véhicule(s)</span></div><div className="occupancy-search"><label>Rechercher un véhicule ou une date<input value={search} onChange={(event) => { setSearch(event.target.value); setPage(1); }} placeholder="Ex. 5409TBR" /></label><span>10 par page</span></div>{error && <div className="alert error">{error}</div>}<div className="occupancy-grid">{visibleRows.length ? visibleRows.map((row) => { const capacity = 18; const rate = Math.min(100, Math.round((Number(row.occupied || 0) / capacity) * 100)); return <article className="occupancy-card" key={`${row.vehicle}-${row.day}`}><div><strong>{row.vehicle}</strong><small>{row.day}</small></div><strong className="occupancy-rate">{rate}%</strong><span>{row.occupied} / {capacity} places</span><div className="occupancy-bar"><i style={{ width: `${rate}%` }} /></div></article>; }) : <p className="muted">{rows.length ? 'Aucun résultat pour cette recherche.' : emptyMessage}</p>}</div><Pagination page={page} pages={pages} onChange={setPage} /></section>;
}

function Dashboard() {
  const [quitus, setQuitus] = useState([]); const [loading, setLoading] = useState(true); const [selectedDate, setSelectedDate] = useState(localTodayKey());
  useEffect(() => { api('dashboard/quitus').then((result) => setQuitus(result.results || [])).finally(() => setLoading(false)); }, []);
  const filteredQuitus = selectedDate ? quitus.filter((row) => quitusInWindow(row, selectedDate)) : quitus;
  const data = dashboardData(filteredQuitus);
  const trendData = dashboardData(quitus);
  if (loading) return <section className="panel"><div className="dashboard-loading">Chargement des données opérationnelles…</div></section>;
  return <div className="dashboard-content"><div className="dashboard-welcome"><div><p className="eyebrow">VUE OPÉRATIONNELLE</p><h2>Activité du réseau</h2><p className="muted">Départs du jour entre 00:01 et 21:00.</p></div><div className="dashboard-filters"><label htmlFor="dashboard-date">Journée du</label><input id="dashboard-date" type="date" value={selectedDate} onChange={(event) => setSelectedDate(event.target.value)} /><small>Plage : 00:01 — 21:00</small></div></div><div className="metric-grid"><Metric icon="♙" label="Total voyageurs" value={data.passengers} hint="sur la plage sélectionnée" /><Metric icon="▣" label="Véhicules" value={data.vehicles} hint="véhicules distincts" /><Metric icon="♟" label="Coopératives actives" value={data.cooperativesCount} hint="ayant envoyé un véhicule ce jour" /><Metric icon="⌖" label="Destinations" value={data.destinationsCount} hint="destinations distinctes" /></div><div className="dashboard-grid"><DashboardMap points={data.points} /><SevenDaysChart values={trendData.days} /></div><div className="dashboard-grid lower"><HourlyChart values={data.hours} /><DestinationBars values={data.destinations} /></div></div>;
}

function AdminDocumentsShellV2({ user, onLogout, onBack }) { const show = (index) => document.querySelectorAll('.document-status-panel')[index]?.scrollIntoView({ behavior: 'smooth', block: 'start' }); return <div className="app-shell"><TopBar user={user} onLogout={onLogout} /><aside><div className="brand"><span>🚐</span><div><strong>CPP-Transport</strong><small>ESPACE TRANSPORT</small></div></div><nav><button onClick={onBack}><b>⌂</b><span>Tableau de bord</span></button><button className="active"><b>▤</b><span>Gestion documents</span></button></nav></aside><main><header><div><p className="eyebrow">ADMINISTRATION</p><h1>Gestion des documents</h1></div><button className="secondary-action" onClick={onBack}>Retour</button></header><div className="document-section-links"><button onClick={() => show(0)}>Voir expirés</button><button onClick={() => show(1)}>Voir bientôt expirés</button><button onClick={() => show(2)}>Voir à jour</button><button onClick={() => show(3)}>Voir dates manquantes</button></div><AdminDocuments /></main></div>; }

function AdminDocumentsShell({ user, onLogout, onBack }) { return <div className="app-shell"><TopBar user={user} onLogout={onLogout} /><main><AdminDocuments /></main></div>; }

function AdminDocumentsLegacy() { const [tab, setTab] = useState('vehicles'); const [vehicles, setVehicles] = useState([]); const [drivers, setDrivers] = useState([]); useEffect(() => { Promise.all([api('admin/vehicules'), api('admin/chauffeurs')]).then(([vehicleData, driverData]) => { setVehicles(vehicleData.results || []); setDrivers(driverData.results || []); }); }, []); const photos = (row) => row.photos || {}; const status = (value) => value ? <a href={value} target="_blank" rel="noreferrer">Disponible</a> : <span className="document-missing">Manquant</span>; return <div className="documents-page"><div className="report-tabs"><button className={tab === 'vehicles' ? 'active' : ''} onClick={() => setTab('vehicles')}>Documents véhicules</button><button className={tab === 'drivers' ? 'active' : ''} onClick={() => setTab('drivers')}>Documents chauffeurs</button></div><section className="panel"><div className="table-wrap"><table><thead>{tab === 'vehicles' ? <tr><th>Véhicule</th><th>Devant</th><th>Derrière</th><th>Gauche</th><th>Droite</th><th>Intérieur</th></tr> : <tr><th>Chauffeur</th><th>Photo</th><th>CIN recto</th><th>CIN verso</th><th>Permis recto</th><th>Permis verso</th></tr>}</thead><tbody>{(tab === 'vehicles' ? vehicles : drivers).map((row) => { const files = photos(row); return tab === 'vehicles' ? <tr key={row.objectId}><td>{row.numero || row.numeroVehicule || row.immatriculation || '—'}</td><td>{status(files.front)}</td><td>{status(files.back)}</td><td>{status(files.left)}</td><td>{status(files.right)}</td><td>{status(files.interior)}</td></tr> : <tr key={row.objectId}><td>{`${row.nom || ''} ${row.prenom || ''}`.trim() || row.name || '—'}</td><td>{status(files.portrait)}</td><td>{status(files.cinFront)}</td><td>{status(files.cinBack)}</td><td>{status(files.licenseFront)}</td><td>{status(files.licenseBack)}</td></tr>; })}</tbody></table></div></section></div>; }

function AdminDocuments() { const [tab, setTab] = useState('vehicles'); const [vehicles, setVehicles] = useState([]); const [drivers, setDrivers] = useState([]); useEffect(() => { Promise.all([api('admin/vehicules'), api('admin/chauffeurs')]).then(([vehicleData, driverData]) => { setVehicles(vehicleData.results || []); setDrivers(driverData.results || []); }); }, []); const today = new Date(); const classify = (raw) => { if (!raw) return 'missing'; const date = new Date(raw); if (Number.isNaN(date.getTime())) return 'missing'; const days = Math.ceil((date - today) / 86400000); return days < 0 ? 'expired' : days <= 15 ? 'soon' : 'valid'; }; const rows = tab === 'vehicles' ? vehicles : drivers; const documentRows = rows.flatMap((row) => { const name = tab === 'vehicles' ? (row.numero || row.immatriculation || 'Véhicule') : (`${row.nom || ''} ${row.prenom || ''}`.trim() || 'Chauffeur'); const documents = tab === 'vehicles' ? [['Photo devant', 'front'], ['Photo derrière', 'back'], ['Photo gauche', 'left'], ['Photo droite', 'right'], ['Photo intérieur', 'interior']] : [['Photo chauffeur', 'portrait'], ['CIN recto', 'cinFront'], ['CIN verso', 'cinBack'], ['Permis recto', 'licenseFront'], ['Permis verso', 'licenseBack']]; return documents.map(([label, key]) => ({ name, label, file: row.photos?.[key], state: classify(row.documentExpiry?.[key] || row.expirations?.[key] || row[`${key}Expiry`]) })); }); const section = (title, state) => <section className="panel document-status-panel"><div className="panel-heading"><div><p className="eyebrow">DOCUMENTS</p><h2>{title}</h2></div><span className="result-count">{documentRows.filter((item) => item.state === state).length}</span></div><div className="document-status-list">{documentRows.filter((item) => item.state === state).map((item, index) => <div className="document-status-row" key={`${item.name}-${item.label}-${index}`}><strong>{item.name}</strong><span>{item.label}</span>{item.file ? <a href={item.file} target="_blank" rel="noreferrer">Voir</a> : <em>Document manquant</em>}</div>)}{!documentRows.some((item) => item.state === state) && <p className="muted">Aucun document dans cette catégorie.</p>}</div></section>; return <div className="documents-page"><div className="report-tabs"><button className={tab === 'vehicles' ? 'active' : ''} onClick={() => setTab('vehicles')}>Véhicules</button><button className={tab === 'drivers' ? 'active' : ''} onClick={() => setTab('drivers')}>Chauffeurs</button></div>{section('Papiers expirés', 'expired')}{section('Expiration dans 15 jours', 'soon')}{section('Papiers à jour', 'valid')}{section('Dates à renseigner', 'missing')}</div>; }

function AdminSettingsShell({ user, onLogout, onBack }) { const [open, setOpen] = useState(true); const [subpage, setSubpage] = useState(null); return <div className="app-shell"><TopBar user={user} onLogout={onLogout} /><aside><div className="brand"><span>🚐</span><div><strong>CPP-Transport</strong><small>ESPACE TRANSPORT</small></div></div><nav><button onClick={onBack}><b>⌂</b><span>Tableau de bord</span></button><button className="active" onClick={() => setOpen((value) => !value)}><b>⚙</b><span>Paramètres</span><em>{open ? '−' : '+'}</em></button>{open && <button className={`submenu-active ${subpage === 'users' ? 'selected' : ''}`} onClick={() => setSubpage('users')}><b>↳</b><span>Gestion utilisateurs</span></button>}</nav></aside><main><header><div><p className="eyebrow">ESPACE TRANSPORT</p><h1>{subpage === 'users' ? 'Gestion utilisateurs' : 'Paramètres'}</h1></div></header>{subpage === 'users' ? <AdminSettings onBack={onBack} /> : <section className="panel settings-empty"><h2>Paramètres</h2><p className="muted">Ouvrez « Gestion utilisateurs » dans le sous-menu pour afficher la liste.</p></section>}</main></div>; }

function AdminSettings({ onBack }) {
  const [users, setUsers] = useState([]); const [cooperatives, setCooperatives] = useState([]); const [search, setSearch] = useState(''); const [modal, setModal] = useState(false); const [role, setRole] = useState('Membre Cpp'); const [error, setError] = useState('');
  const load = () => Promise.all([api('admin/users'), api('cooperative')]).then(([userData, cooperativeData]) => { setUsers(userData.results || []); setCooperatives(cooperativeData.results || []); }).catch((errorValue) => setError(errorValue.message)); useEffect(() => { load(); }, []); const visible = users.filter((item) => `${item.username || ''} ${item.fullName || ''} ${item.role || ''}`.toLocaleLowerCase('fr-FR').includes(search.toLocaleLowerCase('fr-FR')));
  const submit = async (event) => { event.preventDefault(); const form = event.currentTarget; const body = Object.fromEntries(new FormData(form).entries()); try { await api('admin/users', { method: 'POST', body: JSON.stringify(body) }); form.reset(); setRole('Membre Cpp'); setModal(false); load(); } catch (errorValue) { setError(errorValue.message); } };
  return <div className="settings-page"><div className="panel-heading"><div><p className="eyebrow">ADMINISTRATION</p><h2>Paramètres · Utilisateurs</h2><p className="muted">Gérez les accès des membres de l’espace transport.</p></div><div className="panel-actions"><button className="secondary-action" onClick={onBack}>Retour</button><button onClick={() => { setModal(true); setError(''); }}>+ Créer un utilisateur</button></div></div><section className="panel"><input className="search-input user-search" value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Rechercher un utilisateur, un rôle…" /><div className="table-wrap"><table><thead><tr><th>Nom d’utilisateur</th><th>Nom complet</th><th>Rôle</th><th>Statut</th></tr></thead><tbody>{visible.length ? visible.map((item) => <tr key={item.objectId}><td>{item.username || '—'}</td><td>{item.fullName || '—'}</td><td>{item.role || '—'}</td><td>{item.actif === false ? 'Inactif' : 'Actif'}</td></tr>) : <tr><td colSpan="4" className="muted">Aucun utilisateur trouvé.</td></tr>}</tbody></table></div></section>{modal && <div className="modal-backdrop"><form className="modal-card form-modal" onSubmit={submit}><button type="button" className="modal-close" onClick={() => setModal(false)}>×</button><p className="eyebrow">NOUVEL UTILISATEUR</p><h2>Créer un accès</h2><label>Nom d’utilisateur<input name="username" required autoFocus /></label><label>Mot de passe<input name="password" type="password" minLength="4" defaultValue="1234" required /></label><label>Rôle<select name="role" value={role} onChange={(event) => setRole(event.target.value)}><option value="Membre Cpp">Membre Cpp</option><option value="ATT">Agent gare</option><option value="Cooperative">Cooperative</option><option value="Admin">Admin</option></select></label>{role === 'Cooperative' && <label>Coopérative<select name="cooperativeId" required><option value="">Sélectionner une coopérative</option>{cooperatives.filter((item) => !item.hasAccount).map((item) => <option value={item.objectId} key={item.objectId}>{item.name}</option>)}</select><small className="muted">Le compte sera automatiquement rattaché à cette coopérative.</small></label>}<label>Nom complet<input name="fullName" /></label>{error && <div className="alert error">{error}</div>}<div className="modal-actions"><button type="submit">Créer</button><button type="button" className="secondary-action" onClick={() => setModal(false)}>Annuler</button></div></form></div>}</div>;
}

function PlanningShell({ user, onLogout, onBack, onNavigate }) { const visible = Object.entries(modules).filter(([key]) => !['vehicules', 'chauffeurs', 'parametres', 'documents'].includes(key) || user.role === 'Admin'); const go = (key) => { if (key !== 'planning') onNavigate(key); }; return <div className="app-shell"><TopBar user={user} onLogout={onLogout} /><aside><div className="brand"><span>🚐</span><div><strong>CPP-Transport</strong><small>ESPACE TRANSPORT</small></div></div><nav>{visible.map(([key, label]) => <button className={key === 'planning' ? 'active' : ''} onClick={() => go(key)} key={key}><b>{moduleIcons[key]}</b><span>{label}</span></button>)}</nav></aside><main><header><div><p className="eyebrow">ORGANISATION</p><h1>Planning prévisionnel</h1></div><button className="secondary-action" onClick={onBack}>Retour</button></header><Planning user={user} /></main></div>; }

function Planning({ user, hideModels = false }) { const [models, setModels] = useState([]); const [plans, setPlans] = useState([]); const [modal, setModal] = useState(null); const [error, setError] = useState(''); const [success, setSuccess] = useState(''); const load = () => Promise.all([api('planning-models'), api('planning')]).then(([modelData, planData]) => { setModels(modelData.results || []); setPlans(planData.results || []); }).catch((errorValue) => setError(errorValue.message)); useEffect(() => { load(); }, []); const submit = async (event) => { event.preventDefault(); const body = Object.fromEntries(new FormData(event.currentTarget).entries()); try { await api(modal === 'model' ? 'planning-models' : 'planning', { method: 'POST', body: JSON.stringify(body) }); setModal(null); setSuccess('Planning enregistré avec succès.'); load(); } catch (errorValue) { setError(errorValue.message); } }; return <div className="planning-page">{user.role === 'Admin' && !hideModels && <section className="panel"><div className="panel-heading"><div><p className="eyebrow">MODÈLES</p><h2>Planning prévisionnel modèle</h2><p className="muted">Créez des modèles réutilisables par les coopératives.</p></div><button onClick={() => setModal('model')}>+ Nouveau modèle</button></div><div className="planning-models">{models.length ? models.map((model) => <article key={model.objectId}><strong>{model.vehiculeModele || model.name}</strong><span>{model.places || 0} place(s)</span><small>{model.depart || '—'} → {model.destination || '—'}</small><button className="action-button edit" onClick={() => setModal(model)}>Utiliser</button></article>) : <p className="muted">Aucun modèle créé.</p>}</div></section>}<section className="panel"><div className="panel-heading"><div><p className="eyebrow">COOPÉRATIVES</p><h2>Planning par coopérative</h2></div><button onClick={() => setModal('planning')}>+ Ajouter un planning</button></div>{success && <div className="alert success">{success}</div>}{error && <div className="alert error">{error}</div>}<div className="table-wrap"><table><thead><tr><th>Date</th><th>Départ</th><th>Destination</th><th>Axe</th><th>Zone</th><th>Catégorie</th><th>Places</th></tr></thead><tbody>{plans.length ? plans.map((plan) => <tr key={plan.objectId}><td>{plan.date || '—'}</td><td>{plan.depart || '—'}</td><td>{plan.destination || '—'}</td><td>{plan.axe || '—'}</td><td>{plan.zone || '—'}</td><td>{plan.category || '—'}</td><td>{plan.places || '—'}</td></tr>) : <tr><td colSpan="7" className="muted">Aucun planning.</td></tr>}</tbody></table></div></section>{modal && <div className="modal-backdrop"><form className="modal-card form-modal" onSubmit={submit}><button type="button" className="modal-close" onClick={() => setModal(null)}>×</button><h2>{modal === 'model' ? 'Nouveau modèle de planning' : 'Ajouter au planning'}</h2>{modal === 'model' && <label>Nom du modèle<input name="name" required /></label>}{modal === 'model' && <><label>Type véhicule<input name="vehiculeModele" placeholder="V1" required /></label><label>Nombre de places<input name="places" type="number" min="1" required /></label></>}{modal !== 'model' && <label>Modèle véhicule<select name="model" required><option value="">Sélectionner un modèle</option>{models.map((model) => <option key={model.objectId} value={model.objectId}>{model.vehiculeModele || model.name} · {model.places || 0} places</option>)}</select></label>}{modal?.objectId && <input type="hidden" name="model" value={modal.objectId} />}<label>Départ<input name="depart" defaultValue={modal?.depart || ''} /></label><label>Destination<input name="destination" defaultValue={modal?.destination || ''} /></label><label>Axe<input name="axe" defaultValue={modal?.axe || ''} /></label><label>Zone<input name="zone" defaultValue={modal?.zone || ''} /></label><label>Catégorie<select name="category" defaultValue={modal?.category || 'Regional'}><option>Regional</option><option>National</option></select></label><label>Date<input name="date" type="date" required /></label><label>Heure<input name="heure" type="time" /></label><label>Véhicule<input name="vehiculeNumero" /></label><label>Chauffeur<input name="chauffeurNom" /></label>{modal !== 'model' && <label>Places<input name="places" type="number" min="0" /></label>}<div className="modal-actions"><button type="submit">Enregistrer</button><button type="button" className="secondary-action" onClick={() => setModal(null)}>Annuler</button></div></form></div>}</div>; }

function PlanningCalendarShell({ user, onLogout, onBack, onNavigate }) { const visible = Object.entries(modules).filter(([key]) => !['vehicules', 'chauffeurs', 'parametres', 'documents'].includes(key) || user.role === 'Admin'); const go = (key) => { if (key !== 'planning') onNavigate(key); }; return <div className="app-shell"><TopBar user={user} onLogout={onLogout} /><aside><nav>{visible.map(([key, label]) => <button className={key === 'planning' ? 'active' : ''} onClick={() => go(key)} key={key}><b>{moduleIcons[key]}</b><span>{label}</span></button>)}</nav></aside><main><header><div><p className="eyebrow">ORGANISATION</p><h1>Planning prévisionnel</h1></div><button className="secondary-action" onClick={onBack}>Retour</button></header><PlanningModelCatalog user={user} /><Planning user={user} hideModels /></main></div>; }

function PlanningModelCatalog({ user }) { const [models, setModels] = useState([]); const [open, setOpen] = useState(false); const [error, setError] = useState(''); const [success, setSuccess] = useState(''); const load = () => api('planning-models').then((result) => setModels(result.results || [])).catch((errorValue) => setError(errorValue.message)); useEffect(() => { load(); }, []); const submit = async (event) => { event.preventDefault(); setError(''); setSuccess(''); const form = event.currentTarget; const body = Object.fromEntries(new FormData(form).entries()); try { await api('planning-models', { method: 'POST', body: JSON.stringify(body) }); form.reset(); setOpen(false); setSuccess(`Le modèle ${body.vehiculeModele} (${body.places} places) a été enregistré avec succès.`); load(); } catch (errorValue) { setError(errorValue.message); } }; return <section className="panel planning-model-catalog"><div className="panel-heading"><div><p className="eyebrow">MODÈLES VÉHICULES</p><h2>Modèles utilisables par les coopératives</h2><p className="muted">Créez un modèle avec son type, par exemple V1, et sa capacité.</p></div>{user.role === 'Admin' && <button onClick={() => { setSuccess(''); setError(''); setOpen(true); }}>+ Nouveau modèle</button>}</div>{success && <div className="alert success">{success}</div>}{error && <div className="alert error">{error}</div>}<div className="planning-model-cards">{models.length ? models.map((model) => <article key={model.objectId}><strong>{model.vehiculeModele || model.modele || model.name || 'Modèle'}</strong><span>{model.places || 0} place(s)</span><small>{model.name && model.name !== (model.vehiculeModele || model.modele) ? model.name : 'Modèle véhicule'}</small></article>) : <p className="muted">Aucun modèle véhicule créé.</p>}</div>{open && <div className="modal-backdrop"><form className="modal-card form-modal" onSubmit={submit}><button type="button" className="modal-close" onClick={() => setOpen(false)}>×</button><p className="eyebrow">NOUVEAU MODÈLE</p><h2>Créer un modèle véhicule</h2><label>Nom du modèle<input name="name" placeholder="Modèle V1" required /></label><label>Type / modèle véhicule<input name="vehiculeModele" placeholder="V1" required /></label><label>Nombre de places<input name="places" type="number" min="1" placeholder="18" required /></label><div className="modal-actions"><button type="submit">Enregistrer</button><button type="button" className="secondary-action" onClick={() => setOpen(false)}>Annuler</button></div></form></div>}</section>; }

function PlanningCalendar() { const [models, setModels] = useState([]); const [month, setMonth] = useState(() => new Date()); const [error, setError] = useState(''); useEffect(() => { api('planning-models').then((result) => setModels(result.results || [])).catch((errorValue) => setError(errorValue.message)); }, []); const year = month.getFullYear(); const monthIndex = month.getMonth(); const firstDay = (new Date(year, monthIndex, 1).getDay() + 6) % 7; const daysInMonth = new Date(year, monthIndex + 1, 0).getDate(); const cells = [...Array(firstDay).fill(null), ...Array.from({ length: daysInMonth }, (_, index) => index + 1)]; const modelsByDay = models.reduce((groups, model) => { const value = String(model.date || '').slice(0, 10); if (!value.startsWith(`${year}-${String(monthIndex + 1).padStart(2, '0')}-`)) return groups; const day = Number(value.slice(-2)); groups[day] = [...(groups[day] || []), model]; return groups; }, {}); const title = month.toLocaleDateString('fr-FR', { month: 'long', year: 'numeric' }); return <section className="panel planning-calendar-panel"><div className="panel-heading calendar-toolbar"><div><p className="eyebrow">MODÈLES</p><h2>Modèles en calendrier</h2><p className="muted">Visualisez les départs prévisionnels par date.</p></div><div className="calendar-navigation"><button className="secondary-action" onClick={() => setMonth(new Date(year, monthIndex - 1, 1))}>‹</button><strong>{title.charAt(0).toUpperCase() + title.slice(1)}</strong><button className="secondary-action" onClick={() => setMonth(new Date(year, monthIndex + 1, 1))}>›</button></div></div>{error && <div className="alert error">{error}</div>}<div className="planning-calendar-weekdays">{['Lun', 'Mar', 'Mer', 'Jeu', 'Ven', 'Sam', 'Dim'].map((day) => <span key={day}>{day}</span>)}</div><div className="planning-calendar-grid">{cells.map((day, index) => <div className={`planning-calendar-cell ${day ? '' : 'empty'}`} key={`${day || 'empty'}-${index}`}>{day && <><span className="calendar-day-number">{day}</span><div className="calendar-events">{(modelsByDay[day] || []).map((model) => <article className={`planning-calendar-event ${(model.category || '').toLowerCase()}`} key={model.objectId}><strong>{model.name || 'Modèle'}</strong><small>{model.depart || '—'} → {model.destination || '—'}</small><em>{model.category || '—'}</em></article>)}</div></>}</div>)}</div>{!models.length && <p className="muted calendar-empty-message">Aucun modèle de planning créé.</p>}</section>; }

function PayCatalogTestPage() { const [data, setData] = useState(null); const [loading, setLoading] = useState(true); const [error, setError] = useState(''); useEffect(() => { api('pay-test/catalog-products').then(setData).catch((errorValue) => setError(errorValue.message)).finally(() => setLoading(false)); }, []); return <section className="panel pay-test-page"><div className="panel-heading"><div><p className="eyebrow">TEST INTÉGRATION PAY</p><h2>Catalogues et produits</h2><p className="muted">Coopératives de type FzSbvDYRCr · CompanyProduct filtré par catalogue.</p></div><button className="secondary-action" onClick={() => window.location.reload()}>Actualiser</button></div>{loading && <p className="muted">Chargement des coopératives et produits…</p>}{error && <div className="alert error">{error}</div>}{data && <><div className="pay-test-stats"><article><strong>{data.cooperatives?.length || 0}</strong><span>Coopératives</span></article><article><strong>{data.catalogObjectIds?.length || 0}</strong><span>Catalogues</span></article><article><strong>{data.products?.length || 0}</strong><span>Produits PAY</span></article></div><div className="table-wrap"><table><thead><tr><th>Coopérative</th><th>catalogObjectId</th><th>Produits associés</th></tr></thead><tbody>{data.cooperatives?.length ? data.cooperatives.map((cooperative) => { const catalogId = String(cooperative.catalogObjectId || ''); const products = (data.products || []).filter((product) => String(product.catalog?.objectId || product.catalog || '') === catalogId); return <tr key={cooperative.objectId}><td>{cooperative.name || cooperative.objectId}</td><td><code>{catalogId || '—'}</code></td><td>{products.length ? products.map((product) => <span className="pay-product-chip" key={product.objectId}>{product.name || product.title || product.objectId}</span>) : <span className="muted">Aucun produit</span>}</td></tr>; }) : <tr><td colSpan="3" className="muted">Aucune coopérative trouvée pour ce type.</td></tr>}</tbody></table></div></>}</section>; }

function PayCatalogTestShell({ user, onLogout, onNavigate }) { return <div className="app-shell"><TopBar user={user} onLogout={onLogout} /><aside><FullSidebar user={user} active="pay-test" onNavigate={onNavigate} settingsOpen={false} onToggleSettings={() => onNavigate('parametres')} onSelectUsers={() => onNavigate('parametres')} /></aside><main><header><div><p className="eyebrow">ESPACE ADMINISTRATION</p><h1>Test catalogue PAY</h1></div></header><PayCatalogTestPage /></main></div>; }

function FullSidebar({ user, active, onNavigate, settingsOpen, onToggleSettings, onSelectUsers }) { const visible = Object.entries(modules).filter(([key]) => !['vehicules', 'chauffeurs', 'proprietaires', 'parametres', 'documents', 'pay-test'].includes(key) || user.role === 'Admin' || (key === 'vehicules' && user.role === 'Cooperative') || (key === 'proprietaires' && user.role === 'Cooperative')); return <nav>{visible.map(([key, label]) => key === 'parametres' ? <div key={key}><button className={active === key ? 'active' : ''} onClick={onToggleSettings}><b>{moduleIcons[key]}</b><span>{label}</span><em>{settingsOpen ? '−' : '+'}</em></button>{settingsOpen && <button className="submenu-active selected" onClick={onSelectUsers}><b>↳</b><span>Gestion utilisateurs</span></button>}</div> : <button className={active === key ? 'active' : ''} onClick={() => onNavigate(key)} key={key}><b>{moduleIcons[key]}</b><span>{label}</span></button>)}</nav>; }

function AdminSettingsShellFull({ user, onLogout, onBack, onNavigate }) { const [open, setOpen] = useState(true); return <div className="app-shell"><TopBar user={user} onLogout={onLogout} /><aside><FullSidebar user={user} active="parametres" onNavigate={onNavigate} settingsOpen={open} onToggleSettings={() => setOpen((value) => !value)} onSelectUsers={() => {}} /></aside><main><header><div><p className="eyebrow">ESPACE TRANSPORT</p><h1>Gestion utilisateurs</h1></div><button className="secondary-action" onClick={onBack}>Retour</button></header><AdminSettings onBack={onBack} /></main></div>; }

function AdminDocumentsShellFull({ user, onLogout, onBack, onNavigate }) { const show = (index) => document.querySelectorAll('.document-status-panel')[index]?.scrollIntoView({ behavior: 'smooth', block: 'start' }); return <div className="app-shell"><TopBar user={user} onLogout={onLogout} /><aside><FullSidebar user={user} active="documents" onNavigate={onNavigate} settingsOpen={false} onToggleSettings={() => onNavigate('parametres')} onSelectUsers={() => onNavigate('parametres')} /></aside><main><header><div><p className="eyebrow">ADMINISTRATION</p><h1>Gestion des documents</h1></div><button className="secondary-action" onClick={onBack}>Retour</button></header><div className="document-section-links"><button onClick={() => show(0)}>Voir expirés</button><button onClick={() => show(1)}>Voir bientôt expirés</button><button onClick={() => show(2)}>Voir à jour</button><button onClick={() => show(3)}>Voir dates manquantes</button></div><AdminDocuments /></main></div>; }

function DocumentEditor() { const [tab, setTab] = useState('vehicules'); const [vehicles, setVehicles] = useState([]); const [drivers, setDrivers] = useState([]); const [selected, setSelected] = useState(''); const [documents, setDocuments] = useState({}); const [message, setMessage] = useState(''); const [error, setError] = useState(''); useEffect(() => { Promise.all([api('admin/vehicules'), api('admin/chauffeurs')]).then(([vehicleData, driverData]) => { setVehicles(vehicleData.results || []); setDrivers(driverData.results || []); }).catch((errorValue) => setError(errorValue.message)); }, []); const rows = tab === 'vehicules' ? vehicles : drivers; const choose = (event) => { const id = event.target.value; setSelected(id); const row = rows.find((item) => item.objectId === id); setDocuments(row?.documentExpiry || {}); setMessage(''); }; const update = (event) => setDocuments((old) => ({ ...old, [event.target.name]: event.target.value })); const save = async (event) => { event.preventDefault(); setError(''); setMessage(''); if (!selected) return setError('Sélectionnez un véhicule ou un chauffeur.'); try { await api(`admin/documents/${tab}/${selected}`, { method: 'PUT', body: JSON.stringify({ documentExpiry: documents }) }); setMessage('Les dates des documents ont été enregistrées avec succès.'); const result = await api(tab === 'vehicules' ? 'admin/vehicules' : 'admin/chauffeurs'); if (tab === 'vehicules') setVehicles(result.results || []); else setDrivers(result.results || []); } catch (errorValue) { setError(errorValue.message); } }; const changeTab = (value) => { setTab(value); setSelected(''); setDocuments({}); setMessage(''); setError(''); }; return <section className="panel document-editor"><div className="panel-heading"><div><p className="eyebrow">MISE À JOUR</p><h2>Ajouter les papiers</h2><p className="muted">Enregistrez les dates d’expiration des documents.</p></div></div><div className="report-tabs"><button className={tab === 'vehicules' ? 'active' : ''} onClick={() => changeTab('vehicules')}>Documents véhicules</button><button className={tab === 'chauffeurs' ? 'active' : ''} onClick={() => changeTab('chauffeurs')}>Documents chauffeurs</button></div><form className="document-editor-form" onSubmit={save}><label>{tab === 'vehicules' ? 'Véhicule' : 'Chauffeur'}<select value={selected} onChange={choose} required><option value="">Sélectionner…</option>{rows.map((row) => <option key={row.objectId} value={row.objectId}>{tab === 'vehicules' ? (row.numero || row.immatriculation) : `${row.nom || ''} ${row.prenom || ''}`.trim()}</option>)}</select></label>{tab === 'vehicules' ? <div className="document-date-grid"><label>Assurance<input name="assurance" type="date" value={documents.assurance || ''} onChange={update} /></label><label>Licence<input name="licence" type="date" value={documents.licence || ''} onChange={update} /></label><label>Visite technique<input name="visiteTechnique" type="date" value={documents.visiteTechnique || ''} onChange={update} /></label></div> : <div className="document-date-grid"><label>Permis<input name="permis" type="date" value={documents.permis || ''} onChange={update} /></label><label>Visite permis<input name="visitePermis" type="date" value={documents.visitePermis || ''} onChange={update} /></label></div>} {message && <div className="alert success">{message}</div>}{error && <div className="alert error">{error}</div>}<button type="submit">Enregistrer les documents</button></form></section>; }

function AdminDocumentsShellWithEditor({ user, onLogout, onBack, onNavigate }) { const show = (index) => document.querySelectorAll('.document-status-panel')[index]?.scrollIntoView({ behavior: 'smooth', block: 'start' }); return <div className="app-shell"><TopBar user={user} onLogout={onLogout} /><aside><FullSidebar user={user} active="documents" onNavigate={onNavigate} settingsOpen={false} onToggleSettings={() => onNavigate('parametres')} onSelectUsers={() => onNavigate('parametres')} /></aside><main><header><div><p className="eyebrow">ADMINISTRATION</p><h1>Gestion des documents</h1></div><button className="secondary-action" onClick={onBack}>Retour</button></header><DocumentEditor /><div className="document-section-links"><button onClick={() => show(0)}>Voir expirés</button><button onClick={() => show(1)}>Voir bientôt expirés</button><button onClick={() => show(2)}>Voir à jour</button><button onClick={() => show(3)}>Voir dates manquantes</button></div><AdminDocuments /></main></div>; }

function AdminSettingsLegacy({ onBack }) {
  const [users, setUsers] = useState([]); const [modal, setModal] = useState(false); const [error, setError] = useState('');
  const load = () => api('admin/users').then((result) => setUsers(result.results || [])).catch((errorValue) => setError(errorValue.message));
  useEffect(() => { load(); }, []);
  const submit = async (event) => { event.preventDefault(); const body = Object.fromEntries(new FormData(event.currentTarget).entries()); try { await api('admin/users', { method: 'POST', body: JSON.stringify(body) }); setModal(false); event.currentTarget.reset(); load(); } catch (errorValue) { setError(errorValue.message); } };
  return <div className="settings-page"><div className="panel-heading"><div><p className="eyebrow">ADMINISTRATION</p><h2>Paramètres · Utilisateurs</h2><p className="muted">Gérez les accès des membres de l’espace transport.</p></div><div className="panel-actions"><button className="secondary-action" onClick={onBack}>Retour</button><button onClick={() => { setModal(true); setError(''); }}>+ Créer un utilisateur</button></div></div><section className="panel"><div className="table-wrap"><table><thead><tr><th>Nom d’utilisateur</th><th>Nom complet</th><th>Rôle</th><th>Statut</th></tr></thead><tbody>{users.length ? users.map((item) => <tr key={item.objectId}><td>{item.username || '—'}</td><td>{item.fullName || '—'}</td><td>{item.role || '—'}</td><td>{item.actif === false ? 'Inactif' : 'Actif'}</td></tr>) : <tr><td colSpan="4" className="muted">Aucun utilisateur.</td></tr>}</tbody></table></div></section>{modal && <div className="modal-backdrop"><form className="modal-card form-modal" onSubmit={submit}><button type="button" className="modal-close" onClick={() => setModal(false)}>×</button><p className="eyebrow">NOUVEL UTILISATEUR</p><h2>Créer un accès</h2><label>Nom d’utilisateur<input name="username" required autoFocus /></label><label>Mot de passe<input name="password" type="password" minLength="4" defaultValue="1234" required /></label><label>Rôle<select name="role" defaultValue="Membre Cpp"><option value="Membre Cpp">Membre Cpp</option><option value="ATT">Agent gare</option><option value="Cooperative">Cooperative</option><option value="Admin">Admin</option></select></label><label>Nom complet<input name="fullName" /></label>{error && <div className="alert error">{error}</div>}<div className="modal-actions"><button type="submit">Créer</button><button type="button" className="secondary-action" onClick={() => setModal(false)}>Annuler</button></div></form></div>}</div>;
}

function Pagination({ page, pages, onChange }) { if (pages <= 1) return null; return <div className="pagination"><span>Page {page} / {pages}</span><div><button disabled={page === 1} onClick={() => onChange(page - 1)}>‹</button><button disabled={page === pages} onClick={() => onChange(page + 1)}>›</button></div></div>; }

function AdminRegistry({ type }) { return type === 'vehicules' ? <><VehicleTableOnly /><VehicleCreateForm /></> : <><DriverTableWithPermit /><DriverCreateForm /></>; }

function DriverTableWithPermit() { const [rows, setRows] = useState([]); const [page, setPage] = useState(1); const [selected, setSelected] = useState(null); const [message, setMessage] = useState(''); const [error, setError] = useState(''); const size = 10; const load = () => api('admin/chauffeurs').then((result) => setRows(result.results || [])).catch((errorValue) => setError(errorValue.message)); useEffect(() => { load(); }, []); const remove = async (row) => { if (!window.confirm(`Supprimer le chauffeur ${row.nom || ''} ?`)) return; try { await api(`admin/chauffeurs/${row.objectId}`, { method: 'DELETE' }); setMessage('Chauffeur supprimé avec succès.'); load(); } catch (errorValue) { setError(errorValue.message); } }; const save = async (event) => { event.preventDefault(); const body = Object.fromEntries(new FormData(event.currentTarget).entries()); try { await api(`admin/chauffeurs/${selected.objectId}`, { method: 'PUT', body: JSON.stringify(body) }); setSelected(null); setMessage('Chauffeur modifié avec succès.'); load(); } catch (errorValue) { setError(errorValue.message); } }; const pages = Math.max(1, Math.ceil(rows.length / size)); const visible = rows.slice((page - 1) * size, page * size); return <section className="panel"><div className="panel-heading"><div><p className="eyebrow">ADMINISTRATION</p><h2>Gestion des chauffeurs</h2></div><span className="result-count">{rows.length} chauffeur(s)</span></div>{message && <div className="alert success">{message}</div>}{error && <div className="alert error">{error}</div>}<div className="table-wrap"><table><thead><tr><th>Nom</th><th>Prénom</th><th>Téléphone</th><th>Catégorie permis</th><th>N° permis</th><th>Statut</th><th>Actions</th></tr></thead><tbody>{visible.length ? visible.map((row) => <tr key={row.objectId}><td>{row.nom || '—'}</td><td>{row.prenom || '—'}</td><td>{row.telephone || '—'}</td><td>{row.categoriePermis || '—'}</td><td>{row.numeroPermis || row.numPermis || row.permisNumero || '—'}</td><td>{row.statut || 'Actif'}</td><td className="row-actions"><button className="action-button edit" onClick={() => setSelected(row)}>Modifier</button><button className="action-button delete" onClick={() => remove(row)}>Supprimer</button></td></tr>) : <tr><td colSpan="7" className="muted">Aucun chauffeur.</td></tr>}</tbody></table></div><Pagination page={page} pages={pages} onChange={setPage} />{selected && <div className="modal-backdrop"><form className="modal-card form-modal" onSubmit={save}><button type="button" className="modal-close" onClick={() => setSelected(null)}>×</button><h2>Modifier le chauffeur</h2><label>Nom<input name="nom" defaultValue={selected.nom || ''} required /></label><label>Prénom<input name="prenom" defaultValue={selected.prenom || ''} required /></label><label>Téléphone<input name="telephone" defaultValue={selected.telephone || ''} /></label><label>Adresse<input name="adresse" defaultValue={selected.adresse || ''} /></label><label>Catégorie permis<input name="categoriePermis" defaultValue={selected.categoriePermis || ''} /></label><label>N° permis<input name="numeroPermis" defaultValue={selected.numeroPermis || selected.numPermis || selected.permisNumero || ''} /></label><div className="modal-actions"><button type="submit">Enregistrer</button><button type="button" className="secondary-action" onClick={() => setSelected(null)}>Annuler</button></div></form></div>}</section>; }

function DriverTableActive() { const [rows, setRows] = useState([]); const [page, setPage] = useState(1); const [selected, setSelected] = useState(null); const [message, setMessage] = useState(''); const [error, setError] = useState(''); const size = 10; const load = () => api('admin/chauffeurs').then((result) => setRows(result.results || [])).catch((errorValue) => setError(errorValue.message)); useEffect(() => { load(); }, []); const remove = async (row) => { if (!window.confirm(`Supprimer le chauffeur ${row.nom || ''} ?`)) return; try { await api(`admin/chauffeurs/${row.objectId}`, { method: 'DELETE' }); setMessage('Chauffeur supprimé avec succès.'); load(); } catch (errorValue) { setError(errorValue.message); } }; const save = async (event) => { event.preventDefault(); const body = Object.fromEntries(new FormData(event.currentTarget).entries()); try { await api(`admin/chauffeurs/${selected.objectId}`, { method: 'PUT', body: JSON.stringify(body) }); setSelected(null); setMessage('Chauffeur modifié avec succès.'); load(); } catch (errorValue) { setError(errorValue.message); } }; const pages = Math.max(1, Math.ceil(rows.length / size)); const visible = rows.slice((page - 1) * size, page * size); return <section className="panel"><div className="panel-heading"><div><p className="eyebrow">ADMINISTRATION</p><h2>Gestion des chauffeurs</h2></div><span className="result-count">{rows.length} chauffeur(s)</span></div>{message && <div className="alert success">{message}</div>}{error && <div className="alert error">{error}</div>}<div className="table-wrap"><table><thead><tr><th>Nom</th><th>Prénom</th><th>Téléphone</th><th>Catégorie permis</th><th>Statut</th><th>Actions</th></tr></thead><tbody>{visible.length ? visible.map((row) => <tr key={row.objectId}><td>{row.nom || '—'}</td><td>{row.prenom || '—'}</td><td>{row.telephone || '—'}</td><td>{row.categoriePermis || '—'}</td><td>{row.statut || 'Actif'}</td><td className="row-actions"><button className="action-button edit" onClick={() => setSelected(row)}>Modifier</button><button className="action-button delete" onClick={() => remove(row)}>Supprimer</button></td></tr>) : <tr><td colSpan="6" className="muted">Aucun chauffeur.</td></tr>}</tbody></table></div><Pagination page={page} pages={pages} onChange={setPage} />{selected && <div className="modal-backdrop"><form className="modal-card form-modal" onSubmit={save}><button type="button" className="modal-close" onClick={() => setSelected(null)}>×</button><h2>Modifier le chauffeur</h2><label>Nom<input name="nom" defaultValue={selected.nom || ''} required /></label><label>Prénom<input name="prenom" defaultValue={selected.prenom || ''} required /></label><label>Téléphone<input name="telephone" defaultValue={selected.telephone || ''} /></label><label>Adresse<input name="adresse" defaultValue={selected.adresse || ''} /></label><label>Catégorie permis<input name="categoriePermis" defaultValue={selected.categoriePermis || ''} /></label><label>Numéro permis<input name="numeroPermis" defaultValue={selected.numeroPermis || ''} /></label><div className="modal-actions"><button type="submit">Enregistrer</button><button type="button" className="secondary-action" onClick={() => setSelected(null)}>Annuler</button></div></form></div>}</section>; }

function DriverTableOnly() { const [rows, setRows] = useState([]); const [page, setPage] = useState(1); const [message, setMessage] = useState(''); const [error, setError] = useState(''); const size = 10; const load = () => api('admin/chauffeurs').then((result) => setRows(result.results || [])).catch((errorValue) => setError(errorValue.message)); useEffect(() => { load(); }, []); const remove = async (row) => { if (!window.confirm(`Supprimer le chauffeur ${row.nom || ''} ?`)) return; try { await api(`admin/chauffeurs/${row.objectId}`, { method: 'DELETE' }); setMessage('Chauffeur supprimé avec succès.'); load(); } catch (errorValue) { setError(errorValue.message); } }; const pages = Math.max(1, Math.ceil(rows.length / size)); const visible = rows.slice((page - 1) * size, page * size); return <section className="panel"><div className="panel-heading"><div><p className="eyebrow">ADMINISTRATION</p><h2>Gestion des chauffeurs</h2></div><span className="result-count">{rows.length} chauffeur(s)</span></div>{message && <div className="alert success">{message}</div>}{error && <div className="alert error">{error}</div>}<div className="table-wrap"><table><thead><tr><th>Nom</th><th>Prénom</th><th>Téléphone</th><th>Catégorie permis</th><th>Statut</th><th>Actions</th></tr></thead><tbody>{visible.length ? visible.map((row) => <tr key={row.objectId}><td>{row.nom || row.name || '—'}</td><td>{row.prenom || '—'}</td><td>{row.telephone || row.phone || '—'}</td><td>{row.categoriePermis || '—'}</td><td>{row.statut || 'Actif'}</td><td className="row-actions"><button className="action-button edit">Modifier</button><button className="action-button delete" onClick={() => remove(row)}>Supprimer</button></td></tr>) : <tr><td colSpan="6" className="muted">Aucun chauffeur.</td></tr>}</tbody></table></div><Pagination page={page} pages={pages} onChange={setPage} /></section>; }

function DriverCreateForm() { const [open, setOpen] = useState(false); const [message, setMessage] = useState(''); return <><button className="vehicle-create-open" onClick={() => { setMessage(''); setOpen(true); }}>+ Créer un chauffeur</button>{message && <div className="alert success">{message}</div>}{open && <DriverWizardFinal onClose={() => { setOpen(false); setMessage('Chauffeur enregistré avec succès.'); }} />}</>; }

function DriverWizardFinal({ onClose }) { const [step, setStep] = useState(1); const [form, setForm] = useState({ statut: 'Actif' }); const [error, setError] = useState(''); const [saving, setSaving] = useState(false); const update = (event) => setForm((old) => ({ ...old, [event.target.name]: event.target.type === 'file' ? event.target.files[0] : event.target.value })); const upload = async (file) => { if (!file) return ''; const reader = await new Promise((resolve, reject) => { const fr = new FileReader(); fr.onload = () => resolve(fr.result); fr.onerror = reject; fr.readAsDataURL(file); }); const result = await api('cooperative/upload', { method: 'POST', body: JSON.stringify({ filename: file.name, contentType: file.type, base64: reader }) }); return result.url || ''; }; const submit = async () => { setSaving(true); try { const body = { ...form, statut: 'Actif', photos: {} }; for (const side of ['portrait', 'cinFront', 'cinBack', 'licenseFront', 'licenseBack']) body.photos[side] = await upload(form[`photo${side}`]); ['photoPortrait', 'photoCinFront', 'photoCinBack', 'photoLicenseFront', 'photoLicenseBack'].forEach((key) => delete body[key]); await api('admin/chauffeurs', { method: 'POST', body: JSON.stringify(body) }); onClose(); } catch (errorValue) { setError(errorValue.message); } finally { setSaving(false); } }; return <div className="modal-backdrop"><div className="modal-card vehicle-wizard"><button className="modal-close" onClick={onClose}>×</button><p className="eyebrow">NOUVEAU CHAUFFEUR</p><h2>Créer un chauffeur</h2><div className="wizard-steps"><span className={step >= 1 ? 'active' : ''}>1. Identité</span><span className={step >= 2 ? 'active' : ''}>2. Permis</span><span className={step >= 3 ? 'active' : ''}>3. Documents</span></div>{step === 1 && <div className="vehicle-create-grid"><label className="identity-photo">Photo du chauffeur<input name="photoPortrait" type="file" accept="image/*" onChange={update} /></label><label>Nom<input name="nom" value={form.nom || ''} onChange={update} required /></label><label>Prénom<input name="prenom" value={form.prenom || ''} onChange={update} required /></label><label>Téléphone<input name="telephone" value={form.telephone || ''} onChange={update} /></label><label>Adresse<input name="adresse" value={form.adresse || ''} onChange={update} /></label></div>}{step === 2 && <div className="vehicle-create-grid"><label>Catégorie de permis<select name="categoriePermis" value={form.categoriePermis || ''} onChange={update} required><option value="">Sélectionner</option><option>A</option><option>A1</option><option>B</option><option>C</option><option>D</option><option>E</option></select></label><label>Numéro du permis<input name="numeroPermis" value={form.numeroPermis || ''} onChange={update} required /></label></div>}{step === 3 && <div className="vehicle-create-grid photo-grid"><label>CIN recto<input name="photoCinFront" type="file" accept="image/*" onChange={update} /></label><label>CIN verso<input name="photoCinBack" type="file" accept="image/*" onChange={update} /></label><label>Permis recto<input name="photoLicenseFront" type="file" accept="image/*" onChange={update} /></label><label>Permis verso<input name="photoLicenseBack" type="file" accept="image/*" onChange={update} /></label></div>}{error && <div className="alert error">{error}</div>}<div className="modal-actions">{step > 1 && <button type="button" className="secondary-action" onClick={() => setStep(step - 1)}>Précédent</button>}{step < 3 ? <button type="button" onClick={() => setStep(step + 1)}>Suivant</button> : <button type="button" onClick={submit} disabled={saving}>{saving ? 'Enregistrement…' : 'Créer le chauffeur'}</button>}<button type="button" className="secondary-action" onClick={onClose}>Annuler</button></div></div></div>; }

function DriverWizardIdentity({ onClose }) { const [step, setStep] = useState(1); const [form, setForm] = useState({}); const [error, setError] = useState(''); const [saving, setSaving] = useState(false); const update = (event) => setForm((old) => ({ ...old, [event.target.name]: event.target.type === 'file' ? event.target.files[0] : event.target.value })); const upload = async (file) => { if (!file) return ''; const reader = await new Promise((resolve, reject) => { const fr = new FileReader(); fr.onload = () => resolve(fr.result); fr.onerror = reject; fr.readAsDataURL(file); }); const result = await api('cooperative/upload', { method: 'POST', body: JSON.stringify({ filename: file.name, contentType: file.type, base64: reader }) }); return result.url || ''; }; const submit = async () => { setSaving(true); try { const body = { ...form, photos: {} }; for (const side of ['portrait', 'cinFront', 'cinBack', 'licenseFront', 'licenseBack']) body.photos[side] = await upload(form[`photo${side}`]); ['photoPortrait', 'photoCinFront', 'photoCinBack', 'photoLicenseFront', 'photoLicenseBack'].forEach((key) => delete body[key]); await api('admin/chauffeurs', { method: 'POST', body: JSON.stringify(body) }); onClose(); } catch (errorValue) { setError(errorValue.message); } finally { setSaving(false); } }; return <div className="modal-backdrop"><div className="modal-card vehicle-wizard"><button className="modal-close" onClick={onClose}>×</button><p className="eyebrow">NOUVEAU CHAUFFEUR</p><h2>Créer un chauffeur</h2><div className="wizard-steps"><span className={step >= 1 ? 'active' : ''}>1. Identité</span><span className={step >= 2 ? 'active' : ''}>2. Permis</span><span className={step >= 3 ? 'active' : ''}>3. Documents</span></div>{step === 1 && <div className="vehicle-create-grid"><label>Nom<input name="nom" value={form.nom || ''} onChange={update} required /></label><label>Prénom<input name="prenom" value={form.prenom || ''} onChange={update} required /></label><label>Téléphone<input name="telephone" value={form.telephone || ''} onChange={update} /></label><label>Adresse<input name="adresse" value={form.adresse || ''} onChange={update} /></label><label className="identity-photo">Photo du chauffeur<input name="photoPortrait" type="file" accept="image/*" onChange={update} /></label></div>}{step === 2 && <div className="vehicle-create-grid"><label>Catégorie de permis<select name="categoriePermis" value={form.categoriePermis || ''} onChange={update} required><option value="">Sélectionner</option><option>A</option><option>A1</option><option>B</option><option>C</option><option>D</option><option>E</option></select></label><label>Statut<select name="statut" value={form.statut || 'Actif'} onChange={update}><option>Actif</option><option>Inactif</option></select></label></div>}{step === 3 && <div className="vehicle-create-grid photo-grid"><label>CIN recto<input name="photoCinFront" type="file" accept="image/*" onChange={update} /></label><label>CIN verso<input name="photoCinBack" type="file" accept="image/*" onChange={update} /></label><label>Permis recto<input name="photoLicenseFront" type="file" accept="image/*" onChange={update} /></label><label>Permis verso<input name="photoLicenseBack" type="file" accept="image/*" onChange={update} /></label></div>}{error && <div className="alert error">{error}</div>}<div className="modal-actions">{step > 1 && <button type="button" className="secondary-action" onClick={() => setStep(step - 1)}>Précédent</button>}{step < 3 ? <button type="button" onClick={() => setStep(step + 1)}>Suivant</button> : <button type="button" onClick={submit} disabled={saving}>{saving ? 'Enregistrement…' : 'Créer le chauffeur'}</button>}<button type="button" className="secondary-action" onClick={onClose}>Annuler</button></div></div></div>; }

