  const readable = (item) => item && typeof item === 'object' ? (item.name || item.nom || item.description || item.objectId || '—') : String(item || '—'); const value = (row, names) => { for (const name of names) if (row[name] !== undefined && row[name] !== null && row[name] !== '') return row[name]; return ''; }; const date = (row) => { const parsed = parseQuitusDate(value(row, ['departureDate', 'dateDeparture', 'dateDepart', 'date', 'createdAt'])); return Number.isNaN(parsed.getTime()) ? '—' : parsed.toLocaleDateString('fr-FR'); };
